--
-- Name: accept_organization_invitation("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."accept_organization_invitation"("p_token" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_invite public.organization_invitations%ROWTYPE;
  v_membership public.organization_members%ROWTYPE;
BEGIN
  SELECT * INTO v_invite FROM public.organization_invitations WHERE token = p_token FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Invitation not found';
  END IF;

  IF v_invite.status = 'accepted' THEN
    IF v_invite.accepted_by = auth.uid() THEN
      RETURN v_invite.organization_id;
    ELSE
      RAISE EXCEPTION 'Invitation already accepted';
    END IF;
  END IF;

  IF v_invite.status IN ('revoked','expired','declined') THEN
    RAISE EXCEPTION 'Invitation is no longer valid';
  END IF;

  IF v_invite.expires_at < now() THEN
    UPDATE public.organization_invitations SET status = 'expired' WHERE id = v_invite.id;
    RAISE EXCEPTION 'Invitation expired';
  END IF;

  INSERT INTO public.organization_members (
    organization_id, user_id, role, status, invited_by, invited_at, joined_at,
    department_ids, team_ids, last_login_at
  ) VALUES (
    v_invite.organization_id, auth.uid(), v_invite.role, 'active', v_invite.invited_by,
    v_invite.created_at, now(),
    CASE WHEN v_invite.department_id IS NOT NULL THEN jsonb_build_array(v_invite.department_id) ELSE '[]'::jsonb END,
    CASE WHEN v_invite.team_id IS NOT NULL THEN jsonb_build_array(v_invite.team_id) ELSE '[]'::jsonb END,
    now()
  )
  ON CONFLICT (organization_id, user_id) DO UPDATE SET
    status = 'active',
    role = v_invite.role,
    department_ids = CASE WHEN v_invite.department_id IS NOT NULL THEN jsonb_build_array(v_invite.department_id) ELSE EXCLUDED.department_ids END,
    team_ids = CASE WHEN v_invite.team_id IS NOT NULL THEN jsonb_build_array(v_invite.team_id) ELSE EXCLUDED.team_ids END,
    invited_by = COALESCE(organization_members.invited_by, v_invite.invited_by),
    invited_at = COALESCE(organization_members.invited_at, v_invite.created_at),
    joined_at = COALESCE(organization_members.joined_at, now()),
    removed_at = NULL,
    removed_by = NULL,
    updated_at = now();

  SELECT * INTO v_membership FROM public.organization_members
  WHERE organization_id = v_invite.organization_id AND user_id = auth.uid();

  IF v_invite.workspace_id IS NOT NULL THEN
    INSERT INTO public.workspace_members (workspace_id, user_id, role, status, added_by, added_at)
    VALUES (v_invite.workspace_id, auth.uid(), 'contributor', 'active', v_invite.invited_by, now())
    ON CONFLICT (workspace_id, user_id) DO NOTHING;
  END IF;

  UPDATE public.organization_invitations
  SET status = 'accepted', accepted_at = now(), accepted_by = auth.uid()
  WHERE id = v_invite.id;

  INSERT INTO public.audit_logs (organization_id, user_id, action, resource_type, resource_id, details, category, severity)
  VALUES (
    v_invite.organization_id, auth.uid(), 'invitation_accepted', 'organization_invitation', v_invite.id,
    jsonb_build_object('email', v_invite.email, 'role', v_invite.role, 'department_id', v_invite.department_id, 'team_id', v_invite.team_id),
    'user_management', 'info'
  );

  INSERT INTO public.activity_feeds (organization_id, user_id, action, resource_type, resource_id, metadata)
  VALUES (
    v_invite.organization_id, auth.uid(), 'member_joined', 'organization_member', v_membership.id,
    jsonb_build_object('email', v_invite.email, 'role', v_invite.role)
  );

  RETURN v_invite.organization_id;
END;
$$;


--
-- Name: aggregate_automation_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."aggregate_automation_analytics"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO automation_analytics (
    workflow_id, date, starts, completions, failures, conversion_count,
    email_delivered, email_opened, email_clicked, notification_count, recommendation_click, unique_user_count
  )
  SELECT
    e.workflow_id,
    DATE(e.started_at) AS date,
    COUNT(*) FILTER (WHERE e.status IN ('running','delayed','completed','failed')) AS starts,
    COUNT(*) FILTER (WHERE e.status = 'completed') AS completions,
    COUNT(*) FILTER (WHERE e.status = 'failed') AS failures,
    COUNT(DISTINCT e.user_id) FILTER (WHERE l.step_type = 'action' AND (l.result->>'conversion')::boolean) AS conversion_count,
    COUNT(*) FILTER (WHERE l.step_type = 'action' AND l.step_config->>'type' = 'send_email' AND l.status = 'completed') AS email_delivered,
    0 AS email_opened,
    0 AS email_clicked,
    COUNT(*) FILTER (WHERE l.step_type = 'action' AND l.step_config->>'type' = 'in_app_notification' AND l.status = 'completed') AS notification_count,
    COUNT(*) FILTER (WHERE l.step_type = 'action' AND l.step_config->>'type' = 'recommendation' AND l.status = 'completed') AS recommendation_click,
    COUNT(DISTINCT e.user_id)
  FROM automation_executions e
  LEFT JOIN automation_execution_logs l ON l.execution_id = e.id
  WHERE e.started_at >= now() - interval '90 days'
  GROUP BY e.workflow_id, DATE(e.started_at)
  ON CONFLICT (workflow_id, date) DO UPDATE SET
    starts = EXCLUDED.starts,
    completions = EXCLUDED.completions,
    failures = EXCLUDED.failures,
    conversion_count = EXCLUDED.conversion_count,
    email_delivered = EXCLUDED.email_delivered,
    email_opened = EXCLUDED.email_opened,
    email_clicked = EXCLUDED.email_clicked,
    notification_count = EXCLUDED.notification_count,
    recommendation_click = EXCLUDED.recommendation_click,
    unique_user_count = EXCLUDED.unique_user_count;
END;
$$;


--
-- Name: aggregate_organization_analytics_daily(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."aggregate_organization_analytics_daily"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  org record;
  metrics jsonb;
BEGIN
  FOR org IN SELECT id FROM public.organizations WHERE status = 'active' LOOP
    SELECT row_to_json(a.*)::jsonb INTO metrics
    FROM public.get_organization_analytics(org.id) a;

    INSERT INTO public.organization_analytics_snapshots (organization_id, snapshot_date, metrics)
    VALUES (org.id, current_date, COALESCE(metrics, '{}'))
    ON CONFLICT (organization_id, snapshot_date)
    DO UPDATE SET metrics = EXCLUDED.metrics, created_at = now();
  END LOOP;
END;
$$;


--
-- Name: aggregate_personalization_analytics(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."aggregate_personalization_analytics"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_date date := current_date - interval '1 day';
  v_impressions bigint;
  v_clicks bigint;
  v_accepts bigint;
  v_dismissals bigint;
begin
  select
    count(*) filter (where action='impression'),
    count(*) filter (where action='click'),
    count(*) filter (where action='accept'),
    count(*) filter (where action='dismiss')
  into v_impressions, v_clicks, v_accepts, v_dismissals
  from recommendation_events
  where date_trunc('day', created_at) = v_date;

  insert into recommendation_analytics_daily (
    date, impressions, clicks, accepts, dismissals
  ) values (v_date, v_impressions, v_clicks, v_accepts, v_dismissals)
  on conflict (date) do update set
    impressions = EXCLUDED.impressions,
    clicks = EXCLUDED.clicks,
    accepts = EXCLUDED.accepts,
    dismissals = EXCLUDED.dismissals,
    updated_at = now();
end;
$$;


--
-- Name: allocate_team_member_credits("uuid", "text", integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."allocate_team_member_credits"("p_owner_id" "uuid", "p_member_email" "text", "p_allocated_credits" integer, "p_seat_name" "text" DEFAULT NULL::"text", "p_role" "text" DEFAULT 'member'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_owner_credits integer;
  v_total_allocated integer;
  v_member_user_id uuid;
  v_new_total integer;
  v_result jsonb;
BEGIN
  -- Verify owner's plan is Business or Enterprise
  SELECT subscription_plan, COALESCE(credits_balance, 0)
  INTO v_plan, v_owner_credits
  FROM public.profiles
  WHERE id = p_owner_id;

  IF v_plan IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Owner account not found');
  END IF;

  IF v_plan NOT IN ('business', 'enterprise') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Team credit allocation is available only on Business and Enterprise plans');
  END IF;

  -- Check if member already has a registered account
  SELECT id INTO v_member_user_id
  FROM public.profiles
  WHERE lower(email) = lower(p_member_email)
  LIMIT 1;

  -- Check current total allocated excluding this member
  SELECT COALESCE(SUM(allocated_credits), 0)
  INTO v_total_allocated
  FROM public.team_credit_allocations
  WHERE owner_id = p_owner_id
    AND lower(member_email) != lower(p_member_email)
    AND status = 'active';

  v_new_total := v_total_allocated + GREATEST(0, p_allocated_credits);

  -- Ensure allocated sub-quotas do not exceed total pool
  IF v_new_total > v_owner_credits THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('Total allocations (%s credits) cannot exceed shared credit pool (%s credits)', v_new_total, v_owner_credits),
      'available_unallocated', GREATEST(0, v_owner_credits - v_total_allocated)
    );
  END IF;

  -- Upsert allocation
  INSERT INTO public.team_credit_allocations (
    owner_id,
    member_email,
    member_user_id,
    seat_name,
    role,
    allocated_credits,
    status,
    updated_at
  )
  VALUES (
    p_owner_id,
    lower(p_member_email),
    v_member_user_id,
    COALESCE(p_seat_name, split_part(p_member_email, '@', 1)),
    COALESCE(p_role, 'member'),
    GREATEST(0, p_allocated_credits),
    'active',
    now()
  )
  ON CONFLICT (owner_id, member_email)
  DO UPDATE SET
    member_user_id = COALESCE(EXCLUDED.member_user_id, team_credit_allocations.member_user_id),
    seat_name = COALESCE(EXCLUDED.seat_name, team_credit_allocations.seat_name),
    role = EXCLUDED.role,
    allocated_credits = EXCLUDED.allocated_credits,
    status = 'active',
    updated_at = now()
  RETURNING to_jsonb(team_credit_allocations.*) INTO v_result;

  RETURN jsonb_build_object(
    'success', true,
    'allocation', v_result,
    'total_allocated', v_new_total,
    'remaining_unallocated', GREATEST(0, v_owner_credits - v_new_total)
  );
END;
$$;


--
-- Name: anonymize_customer_profile("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."anonymize_customer_profile"("p_profile_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE customer_profiles SET
    email = NULL, full_name = NULL, username = NULL, company = NULL,
    visitor_id = NULL, is_anonymized = true, anonymized_at = now(), gdpr_opt_out_tracking = true
  WHERE id = p_profile_id;

  DELETE FROM customer_devices WHERE customer_profile_id = p_profile_id;
  DELETE FROM customer_interests WHERE customer_profile_id = p_profile_id;
  DELETE FROM privacy_consents WHERE customer_profile_id = p_profile_id;
  DELETE FROM customer_tag_assignments
  WHERE customer_profile_id = p_profile_id AND tag_id IN (SELECT id FROM customer_tags WHERE is_system = false);
END;
$$;


