--
-- Name: can_view_report("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."can_view_report"("p_report_id" "uuid", "p_user_id" "uuid" DEFAULT "auth"."uid"()) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.collaboration_reports r
    WHERE r.id = p_report_id
      AND (
        public.is_workspace_member(r.workspace_id, p_user_id)
        OR EXISTS (
          SELECT 1 FROM public.report_shares s
          WHERE s.report_id = p_report_id AND s.user_id = p_user_id
        )
      )
  );
END;
$$;


--
-- Name: check_entitlement("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."check_entitlement"("p_user_id" "uuid", "p_feature_slug" "text", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS TABLE("allowed" boolean, "reason" "text", "remaining" bigint, "limit_value" bigint, "plan" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_role TEXT := COALESCE(current_setting('role', true), 'anon');
  v_auth_uid UUID := auth.uid();
  v_rate RECORD;
  v_profile RECORD;
  v_cost INT;
  v_trial_eligible BOOLEAN;
BEGIN
  IF v_role <> 'service_role' THEN
    IF v_auth_uid IS NOT NULL THEN
      IF p_user_id IS NOT NULL AND p_user_id <> v_auth_uid THEN
        RAISE EXCEPTION 'Not authorized';
      END IF;
      p_user_id := v_auth_uid;
    ELSE
      p_user_id := NULL;
    END IF;
  END IF;

  SELECT * INTO v_rate FROM credit_rate_table WHERE feature_slug = p_feature_slug;
  IF NOT FOUND THEN
    RETURN QUERY SELECT FALSE, 'This feature has no billing configuration.'::text, 0::bigint, 0::bigint, 'unknown'::text;
    RETURN;
  END IF;
  v_cost := COALESCE(v_rate.base_credit_cost, 1);
  v_trial_eligible := COALESCE(v_rate.trial_eligible, false);

  IF p_user_id IS NULL THEN
    RETURN QUERY SELECT FALSE, 'Guest session required.'::text, 0::bigint, 1::bigint, 'guest'::text;
    RETURN;
  END IF;

  SELECT * INTO v_profile FROM profiles WHERE id = p_user_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT FALSE, 'Profile not found.'::text, 0::bigint, 0::bigint, 'unknown'::text;
    RETURN;
  END IF;

  IF v_trial_eligible AND COALESCE(v_profile.trial_checks_remaining, 0) > 0 THEN
    RETURN QUERY SELECT TRUE, NULL::text,
      COALESCE(v_profile.trial_checks_remaining, 0)::bigint,
      COALESCE(v_profile.trial_checks_total, 5)::bigint,
      COALESCE(v_profile.subscription_plan, 'free')::text;
    RETURN;
  END IF;

  IF COALESCE(v_profile.credits_balance, 0) >= v_cost THEN
    RETURN QUERY SELECT TRUE, NULL::text,
      COALESCE(v_profile.credits_balance, 0)::bigint,
      COALESCE(v_profile.monthly_credit_allocation, 0)::bigint,
      COALESCE(v_profile.subscription_plan, 'free')::text;
    RETURN;
  END IF;

  RETURN QUERY SELECT FALSE,
    CASE WHEN COALESCE(v_profile.subscription_plan, 'free') = 'free'
      THEN 'You''ve used your free checks. Choose a plan to continue.'
      ELSE 'Insufficient credits for this operation. Please top up or renew your plan to continue.' END::text,
    0::bigint, 0::bigint,
    COALESCE(v_profile.subscription_plan, 'free')::text;
END;
$$;


--
-- Name: check_frequency_limit("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."check_frequency_limit"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_limit integer;
  v_count integer;
BEGIN
  SELECT COALESCE(max_messages_per_day, 5) INTO v_limit
  FROM public.communication_preferences
  WHERE user_id = p_user_id;

  IF v_limit IS NULL THEN
    v_limit := 5;
  END IF;

  SELECT COUNT(*) INTO v_count
  FROM public.automation_execution_logs l
  JOIN public.automation_executions e ON l.execution_id = e.id
  WHERE e.user_id = p_user_id
    AND l.step_type = 'action'
    AND l.status = 'completed'
    AND l.timestamp >= now() - interval '1 day';

  RETURN v_count < v_limit;
END;
$$;


--
-- Name: classify_traffic_channel("text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."classify_traffic_channel"("p_referrer" "text", "p_utm_source" "text", "p_utm_medium" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  SELECT CASE
    WHEN p_utm_medium ILIKE '%email%' THEN 'Email Campaign'
    WHEN p_utm_source ILIKE '%google%' AND p_utm_medium ILIKE ANY(ARRAY['%cpc%', '%ppc%', '%paid%']) THEN 'Google Ads'
    WHEN p_utm_source ILIKE '%bing%' AND p_utm_medium ILIKE ANY(ARRAY['%cpc%', '%ppc%', '%paid%']) THEN 'Bing Ads'
    WHEN p_utm_source ILIKE '%facebook%' OR p_referrer ILIKE '%facebook.com%' THEN 'Facebook'
    WHEN p_utm_source ILIKE '%linkedin%' OR p_referrer ILIKE '%linkedin.com%' THEN 'LinkedIn'
    WHEN p_utm_source ILIKE '%twitter%' OR p_referrer ILIKE ANY(ARRAY['%twitter.com%', '%x.com%']) THEN 'Twitter/X'
    WHEN p_utm_source ILIKE '%reddit%' OR p_referrer ILIKE '%reddit.com%' THEN 'Reddit'
    WHEN p_referrer IS NULL OR p_referrer = '' THEN 'Direct'
    WHEN p_referrer ILIKE '%google.%' OR p_referrer ILIKE '%bing.%' OR p_referrer ILIKE '%duckduckgo.%' THEN 'Organic Search'
    WHEN p_referrer NOT ILIKE '%aidetector.cx%' THEN 'Referral Website'
    ELSE 'Direct'
  END;
$$;


--
-- Name: compare_authorship_content("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."compare_authorship_content"("p_tracking_code" "text", "p_content_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_rec RECORD;
  v_match RECORD;
BEGIN
  -- Lookup record
  SELECT id, tracking_code, status, current_version_id
  INTO v_rec
  FROM public.authorship_records
  WHERE tracking_code = p_tracking_code;

  IF NOT FOUND THEN
    -- Fallback to authorship_registrations if legacy tracking code
    SELECT id, tracking_code, status
    INTO v_rec
    FROM public.authorship_registrations
    WHERE tracking_code = p_tracking_code;

    IF NOT FOUND THEN
      RETURN jsonb_build_object(
        'match_status', 'no_match',
        'details', 'Tracking code not found in registry.'
      );
    END IF;
  END IF;

  -- Check exact hash match in private content
  SELECT cp.version_id, cp.canonicalization_version, v.version_number
  INTO v_match
  FROM public.authorship_content_private cp
  LEFT JOIN public.authorship_versions v ON v.id = cp.version_id
  WHERE cp.record_id = v_rec.id AND (cp.canonical_content_hash = p_content_hash OR cp.original_content_hash = p_content_hash)
  LIMIT 1;

  IF FOUND THEN
    IF v_match.version_id = v_rec.current_version_id OR v_match.version_id IS NULL THEN
      RETURN jsonb_build_object(
        'match_status', 'exact_match_current',
        'version_number', COALESCE(v_match.version_number, 1),
        'canonicalization_version', v_match.canonicalization_version,
        'details', 'Exact cryptographic match confirmed with the current registered version.'
      );
    ELSE
      RETURN jsonb_build_object(
        'match_status', 'exact_match_earlier',
        'version_number', v_match.version_number,
        'canonicalization_version', v_match.canonicalization_version,
        'details', 'Exact cryptographic match confirmed with earlier registered version ' || v_match.version_number || '.'
      );
    END IF;
  END IF;

  -- Check legacy registrations
  IF EXISTS (
    SELECT 1 FROM public.authorship_registrations
    WHERE tracking_code = p_tracking_code AND content_hash = p_content_hash
  ) THEN
    RETURN jsonb_build_object(
      'match_status', 'exact_match_current',
      'version_number', 1,
      'canonicalization_version', 'v1.0',
      'details', 'Exact cryptographic match confirmed with registered version.'
    );
  END IF;

  RETURN jsonb_build_object(
    'match_status', 'no_match',
    'details', 'Submitted text hash does not match any registered version of this work.'
  );
END;
$$;


--
-- Name: complete_checklist_item("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."complete_checklist_item"("p_profile_id" "uuid", "p_item_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO user_checklist_progress (customer_profile_id, item_key, completed, completed_at)
  VALUES (p_profile_id, p_item_key, true, now())
  ON CONFLICT (customer_profile_id, item_key)
  DO UPDATE SET completed = true, completed_at = COALESCE(user_checklist_progress.completed_at, now())
  WHERE user_checklist_progress.completed = false;
  RETURN true;
END;
$$;


--
-- Name: decide_approval_step("uuid", integer, "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."decide_approval_step"("p_approval_id" "uuid", "p_step_order" integer, "p_action" "text", "p_comments" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_report_id uuid;
  v_workspace_id uuid;
  v_workflow_id uuid;
  v_current integer;
  v_status approval_status;
  v_total integer;
BEGIN
  SELECT ra.report_id, ra.workflow_id, ra.current_step, ra.status INTO v_report_id, v_workflow_id, v_current, v_status
  FROM public.report_approvals ra WHERE ra.id = p_approval_id;
  IF v_status != 'pending' THEN
    RAISE EXCEPTION 'Approval already decided';
  END IF;
  SELECT workspace_id INTO v_workspace_id FROM public.collaboration_reports WHERE id = v_report_id;
  IF NOT public.is_workspace_admin(v_workspace_id) AND NOT EXISTS (
    SELECT 1 FROM public.approval_steps WHERE approval_id = p_approval_id AND step_order = p_step_order AND approver_user_id = auth.uid()
  ) THEN
    RAISE EXCEPTION 'Not authorized to decide this approval step';
  END IF;
  UPDATE public.approval_steps SET status = p_action::step_status, comments = p_comments, decided_at = now()
  WHERE approval_id = p_approval_id AND step_order = p_step_order;
  IF p_action = 'rejected' THEN
    UPDATE public.report_approvals SET status = 'rejected', completed_at = now() WHERE id = p_approval_id;
    UPDATE public.collaboration_reports SET approval_status = 'rejected' WHERE id = v_report_id;
  ELSE
    SELECT COUNT(*) INTO v_total FROM public.approval_steps WHERE approval_id = p_approval_id;
    IF p_step_order >= v_total THEN
      UPDATE public.report_approvals SET status = 'approved', current_step = p_step_order, completed_at = now() WHERE id = p_approval_id;
      UPDATE public.collaboration_reports SET approval_status = 'approved' WHERE id = v_report_id;
    ELSE
      UPDATE public.report_approvals SET current_step = p_step_order + 1 WHERE id = p_approval_id;
    END IF;
  END IF;
END;
$$;


--
-- Name: detector_perf_by_language(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."detector_perf_by_language"() RETURNS TABLE("language_code" "text", "result_count" bigint, "avg_ai_probability" numeric, "avg_confidence" numeric, "feedback_count" bigint, "incorrect_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT
    COALESCE(r.language_code, 'unknown') AS language_code,
    COUNT(r.id) AS result_count,
    ROUND(AVG(r.ai_probability)::numeric, 2) AS avg_ai_probability,
    ROUND(AVG(r.confidence)::numeric, 2) AS avg_confidence,
    COUNT(f.id) AS feedback_count,
    COUNT(f.id) FILTER (WHERE f.feedback_type = 'incorrect') AS incorrect_count
  FROM detector_results r
  LEFT JOIN detector_feedback f ON f.result_id = r.id
  GROUP BY r.language_code;
$$;


--
-- Name: detector_perf_by_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."detector_perf_by_version"() RETURNS TABLE("detector_version" "text", "result_count" bigint, "avg_ai_probability" numeric, "avg_confidence" numeric, "feedback_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT
    r.detector_version,
    COUNT(r.id) AS result_count,
    ROUND(AVG(r.ai_probability)::numeric, 2) AS avg_ai_probability,
    ROUND(AVG(r.confidence)::numeric, 2) AS avg_confidence,
    COUNT(f.id) AS feedback_count
  FROM detector_results r
  LEFT JOIN detector_feedback f ON f.result_id = r.id
  GROUP BY r.detector_version;
$$;


--
-- Name: detector_problematic_content_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."detector_problematic_content_types"() RETURNS TABLE("content_type" "text", "result_count" bigint, "feedback_count" bigint, "incorrect_count" bigint)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT
    COALESCE(r.content_type, 'unknown') AS content_type,
    COUNT(r.id) AS result_count,
    COUNT(f.id) AS feedback_count,
    COUNT(f.id) FILTER (WHERE f.feedback_type = 'incorrect') AS incorrect_count
  FROM detector_results r
  LEFT JOIN detector_feedback f ON f.result_id = r.id
  GROUP BY r.content_type;
$$;


--
-- Name: evaluate_lifecycle_stages(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."evaluate_lifecycle_stages"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  rec record;
  v_tools int;
  v_active_days int;
  v_last_active timestamptz;
  v_checklist_completed int;
  v_days_since_active int;
  v_new_stage text;
BEGIN
  FOR rec IN SELECT * FROM customer_profiles LOOP
    v_new_stage := rec.lifecycle_stage;

    SELECT COUNT(DISTINCT metadata->>'tool') INTO v_tools
    FROM lead_events
    WHERE customer_profile_id = rec.id AND event_type = 'tool_used' AND created_at > now() - interval '30 days';

    SELECT COUNT(DISTINCT date_trunc('day', created_at)) INTO v_active_days
    FROM lead_events
    WHERE customer_profile_id = rec.id AND created_at > now() - interval '30 days';

    SELECT MAX(created_at) INTO v_last_active
    FROM lead_events
    WHERE customer_profile_id = rec.id;

    SELECT COUNT(*) INTO v_checklist_completed
    FROM user_checklist_progress
    WHERE customer_profile_id = rec.id AND completed = true;

    v_days_since_active := EXTRACT(DAY FROM (now() - COALESCE(v_last_active, rec.created_at)));

    IF rec.email_verified = false OR rec.email_verified IS NULL THEN
      v_new_stage := 'registered';
    ELSIF v_checklist_completed >= 3 AND rec.lifecycle_stage IN ('registered', 'email_verified') THEN
      v_new_stage := 'activated';
    ELSIF v_tools >= 2 AND rec.lifecycle_stage = 'activated' THEN
      v_new_stage := 'engaged';
    ELSIF v_active_days >= 15 AND v_tools >= 3 AND rec.lifecycle_stage IN ('activated', 'engaged') THEN
      v_new_stage := 'power_user';
    END IF;

    IF rec.subscription_plan IS NOT NULL AND rec.subscription_plan <> 'free' THEN
      IF rec.subscription_plan = 'pro' THEN v_new_stage := 'pro_customer';
      ELSIF rec.subscription_plan = 'business' THEN v_new_stage := 'business_customer';
      ELSIF rec.subscription_plan = 'enterprise' THEN v_new_stage := 'enterprise_customer';
      END IF;
    END IF;

    IF v_days_since_active > 60 AND rec.lifecycle_stage NOT IN ('churned') THEN
      v_new_stage := 'churned';
    ELSIF v_days_since_active > 30 AND rec.lifecycle_stage NOT IN ('inactive', 'at_risk', 'churned') THEN
      v_new_stage := 'inactive';
    ELSIF v_days_since_active > 14 AND rec.lifecycle_stage IN ('engaged', 'power_user', 'pro_customer') THEN
      v_new_stage := 'at_risk';
    END IF;

    IF rec.lifecycle_stage = 'churned' AND v_days_since_active <= 30 THEN
      v_new_stage := 'recovered';
    END IF;

    IF v_new_stage IS DISTINCT FROM rec.lifecycle_stage THEN
      UPDATE customer_profiles
      SET lifecycle_stage = v_new_stage,
          previous_stage = rec.lifecycle_stage,
          stage_updated_at = now()
      WHERE id = rec.id;

      INSERT INTO user_lifecycle_history (customer_profile_id, from_stage, to_stage, trigger, changed_at)
      VALUES (rec.id, rec.lifecycle_stage, v_new_stage, 'scheduled_evaluation', now());

      INSERT INTO user_notifications (customer_profile_id, notification_type, title, message, metadata)
      VALUES (rec.id, 'lifecycle_stage_change', 'Stage Updated',
              'Your lifecycle stage changed to ' || v_new_stage,
              jsonb_build_object('from_stage', rec.lifecycle_stage, 'to_stage', v_new_stage));
    END IF;
  END LOOP;
END;
$$;


--
-- Name: evaluate_workflow_condition("jsonb", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."evaluate_workflow_condition"("p_condition" "jsonb", "p_user_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    AS $$
DECLARE
  v_type text := p_condition->>'type';
  v_op text := p_condition->>'operator';
  v_actual numeric;
  v_actual_text text;
  v_actual_bool boolean;
  v_profile public.customer_profiles%ROWTYPE;
  v_usage jsonb;
BEGIN
  IF v_type IS NULL OR v_type = 'group' THEN
    RETURN true;
  END IF;

  SELECT * INTO v_profile FROM public.customer_profiles WHERE user_id = p_user_id LIMIT 1;

  IF v_profile.id IS NOT NULL THEN
    SELECT get_usage_stats(v_profile.id) INTO v_usage;
  END IF;

  CASE v_type
    WHEN 'subscription_plan' THEN
      v_actual_text := COALESCE(v_profile.subscription_plan, 'free');
    WHEN 'lifecycle_stage' THEN
      v_actual_text := v_profile.lifecycle_stage;
    WHEN 'email_verified' THEN
      v_actual_text := CASE WHEN v_profile.email_verified THEN 'true' ELSE 'false' END;
    WHEN 'segment' THEN
      SELECT EXISTS (
        SELECT 1 FROM public.customer_segment_memberships csm
        JOIN public.customer_segments cs ON cs.id = csm.segment_id
        WHERE csm.customer_profile_id = v_profile.id AND cs.name = (p_condition->>'value')
      ) INTO v_actual_bool;
      RETURN COALESCE(v_actual_bool, false);
    WHEN 'detector_usage' THEN
      v_actual := COALESCE((v_usage->>'ai_scans')::numeric, 0);
    WHEN 'humanizer_usage' THEN
      v_actual := COALESCE((v_usage->>'words_humanized')::numeric, 0);
    WHEN 'plagiarism_usage' THEN
      v_actual := COALESCE((v_usage->>'plagiarism_checks')::numeric, 0);
    WHEN 'api_usage' THEN
      v_actual := COALESCE((v_usage->>'api_requests')::numeric, 0);
    WHEN 'days_since_signup' THEN
      v_actual := EXTRACT(DAY FROM now() - v_profile.signup_at);
    WHEN 'days_inactive' THEN
      v_actual := EXTRACT(DAY FROM now() - COALESCE(v_profile.last_login_at, v_profile.signup_at));
    ELSE
      v_actual_text := p_condition->>'actualValue';
  END CASE;

  IF v_type IN ('detector_usage','humanizer_usage','plagiarism_usage','api_usage','days_since_signup','days_inactive') THEN
    CASE v_op
      WHEN 'gt' THEN RETURN v_actual > COALESCE((p_condition->>'value')::numeric, 0);
      WHEN 'gte' THEN RETURN v_actual >= COALESCE((p_condition->>'value')::numeric, 0);
      WHEN 'lt' THEN RETURN v_actual < COALESCE((p_condition->>'value')::numeric, 0);
      WHEN 'lte' THEN RETURN v_actual <= COALESCE((p_condition->>'value')::numeric, 0);
      WHEN 'eq' THEN RETURN v_actual = COALESCE((p_condition->>'value')::numeric, 0);
      WHEN 'neq' THEN RETURN v_actual != COALESCE((p_condition->>'value')::numeric, 0);
      ELSE RETURN false;
    END CASE;
  END IF;

  CASE v_op
    WHEN 'eq' THEN RETURN v_actual_text = COALESCE(p_condition->>'value', '');
    WHEN 'neq' THEN RETURN v_actual_text != COALESCE(p_condition->>'value', '');
    WHEN 'contains' THEN RETURN v_actual_text LIKE '%' || COALESCE(p_condition->>'value', '') || '%';
    WHEN 'not_contains' THEN RETURN v_actual_text NOT LIKE '%' || COALESCE(p_condition->>'value', '') || '%';
    WHEN 'starts_with' THEN RETURN v_actual_text LIKE COALESCE(p_condition->>'value', '') || '%';
    WHEN 'ends_with' THEN RETURN v_actual_text LIKE '%' || COALESCE(p_condition->>'value', '');
    WHEN 'is_empty' THEN RETURN v_actual_text IS NULL OR v_actual_text = '';
    WHEN 'is_not_empty' THEN RETURN v_actual_text IS NOT NULL AND v_actual_text != '';
    ELSE RETURN false;
  END CASE;
END;
$$;


--
-- Name: execute_workflow_action("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."execute_workflow_action"("p_user_id" "uuid", "p_action" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_action_type text := p_action->>'type';
  v_category text := p_action->>'category';
  v_profile public.customer_profiles%ROWTYPE;
  v_result jsonb := jsonb_build_object('success', true);
  v_allowed boolean := true;
  v_tag_id uuid;
  v_segment_id uuid;
  v_product_tips boolean := true;
  v_feature_updates boolean := true;
  v_security_notifications boolean := true;
  v_billing_notifications boolean := true;
  v_marketing_communications boolean := true;
  v_weekly_summaries boolean := true;
  v_email_enabled boolean := true;
  v_in_app_enabled boolean := true;
  v_dashboard_announcements_enabled boolean := true;
BEGIN
  SELECT * INTO v_profile FROM public.customer_profiles WHERE user_id = p_user_id LIMIT 1;

  SELECT
    product_tips,
    feature_updates,
    security_notifications,
    billing_notifications,
    marketing_communications,
    weekly_summaries,
    email_enabled,
    in_app_enabled,
    dashboard_announcements_enabled
  INTO
    v_product_tips,
    v_feature_updates,
    v_security_notifications,
    v_billing_notifications,
    v_marketing_communications,
    v_weekly_summaries,
    v_email_enabled,
    v_in_app_enabled,
    v_dashboard_announcements_enabled
  FROM public.communication_preferences
  WHERE user_id = p_user_id;

  IF v_category IN ('product_tips','feature_updates','marketing_communications','weekly_summaries') THEN
    v_allowed := CASE v_category
      WHEN 'product_tips' THEN v_product_tips
      WHEN 'feature_updates' THEN v_feature_updates
      WHEN 'marketing_communications' THEN v_marketing_communications
      WHEN 'weekly_summaries' THEN v_weekly_summaries
      ELSE true
    END;
  ELSIF v_category IN ('security_notifications','billing_notifications') THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'preference_disabled');
  END IF;

  IF NOT public.check_frequency_limit(p_user_id) THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'frequency_limit');
  END IF;

  CASE v_action_type
    WHEN 'in_app_notification' THEN
      IF v_in_app_enabled THEN
        INSERT INTO public.user_notifications (customer_profile_id, notification_type, title, message, link, metadata, read, created_at)
        VALUES (
          v_profile.id,
          COALESCE(v_category, 'automation'),
          p_action->>'title',
          p_action->>'message',
          p_action->>'link',
          p_action->'metadata',
          false,
          now()
        );
      ELSE
        v_result := jsonb_build_object('success', true, 'skipped', true, 'reason', 'in_app_disabled');
      END IF;
    WHEN 'dashboard_announcement' THEN
      IF v_dashboard_announcements_enabled THEN
        INSERT INTO public.feature_announcements (title, description, cta_text, cta_url, target_segments, priority, enabled, start_date, end_date, created_at)
        VALUES (
          p_action->>'title',
          p_action->>'message',
          p_action->>'cta_text',
          p_action->>'link',
          p_action->'target_segments',
          COALESCE((p_action->>'priority')::int, 1),
          true,
          now(),
          now() + interval '30 days',
          now()
        );
      ELSE
        v_result := jsonb_build_object('success', true, 'skipped', true, 'reason', 'dashboard_announcements_disabled');
      END IF;
    WHEN 'add_tag' THEN
      SELECT id INTO v_tag_id FROM public.customer_tags WHERE name = p_action->>'value' LIMIT 1;
      IF v_tag_id IS NULL THEN
        INSERT INTO public.customer_tags (name, is_system, created_at)
        VALUES (p_action->>'value', false, now())
        RETURNING id INTO v_tag_id;
      END IF;
      INSERT INTO public.customer_tag_assignments (customer_profile_id, tag_id, assigned_by, created_at)
      VALUES (v_profile.id, v_tag_id, 'automation', now())
      ON CONFLICT DO NOTHING;
    WHEN 'remove_tag' THEN
      DELETE FROM public.customer_tag_assignments
      WHERE customer_profile_id = v_profile.id
        AND tag_id = (SELECT id FROM public.customer_tags WHERE name = p_action->>'value' LIMIT 1);
    WHEN 'add_to_segment' THEN
      SELECT id INTO v_segment_id FROM public.customer_segments WHERE name = p_action->>'value' LIMIT 1;
      IF v_segment_id IS NOT NULL THEN
        INSERT INTO public.customer_segment_memberships (customer_profile_id, segment_id, created_at)
        VALUES (v_profile.id, v_segment_id, now())
        ON CONFLICT DO NOTHING;
      END IF;
    WHEN 'remove_from_segment' THEN
      DELETE FROM public.customer_segment_memberships
      WHERE customer_profile_id = v_profile.id
        AND segment_id = (SELECT id FROM public.customer_segments WHERE name = p_action->>'value' LIMIT 1);
    WHEN 'update_lifecycle_stage' THEN
      UPDATE public.customer_profiles
      SET lifecycle_stage = p_action->>'value',
          previous_stage = lifecycle_stage,
          stage_updated_at = now()
      WHERE id = v_profile.id;
    WHEN 'mark_milestone' THEN
      INSERT INTO public.user_milestones (customer_profile_id, milestone_key, unlocked_at)
      VALUES (v_profile.id, p_action->>'value', now())
      ON CONFLICT (customer_profile_id, milestone_key) DO NOTHING;
    WHEN 'recommendation' THEN
      INSERT INTO public.user_recommendations (user_id, recommendation_key, context, created_at)
      VALUES (p_user_id, p_action->>'value', p_action->'context', now());
    WHEN 'admin_notification' THEN
      INSERT INTO public.admin_user_notes (user_id, admin_id, note, created_at)
      VALUES (p_user_id, null, p_action->>'message', now());
    WHEN 'internal_note' THEN
      INSERT INTO public.admin_user_notes (user_id, admin_id, note, created_at)
      VALUES (p_user_id, null, p_action->>'message', now());
    WHEN 'webhook' THEN
      v_result := jsonb_build_object('success', true, 'queued', true, 'url', p_action->>'url');
    ELSE
      v_result := jsonb_build_object('success', true, 'noop', true);
  END CASE;

  RETURN v_result;
END;
$$;


--
-- Name: execute_workflow_action("jsonb", "uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."execute_workflow_action"("p_action" "jsonb", "p_user_id" "uuid", "p_execution_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_action_type text := p_action->>'type';
  v_category text := p_action->>'category';
  v_profile public.customer_profiles%ROWTYPE;
  v_preferences user_communication_preferences%ROWTYPE;
  v_result jsonb := jsonb_build_object('success', true);
  v_allowed boolean := true;
  v_tag_id uuid;
  v_segment_id uuid;
BEGIN
  SELECT * INTO v_profile FROM public.customer_profiles WHERE user_id = p_user_id LIMIT 1;
  SELECT * INTO v_preferences FROM user_communication_preferences WHERE user_id = p_user_id;
  IF v_preferences.user_id IS NULL THEN
    v_preferences := ROW(p_user_id, true, true, true, true, true, true, true, true, true, 5, 'UTC', '22:00', '08:00', now());
  END IF;

  IF v_category IN ('product_tips','feature_updates','marketing_communications','weekly_summaries') THEN
    v_allowed := CASE v_category
      WHEN 'product_tips' THEN v_preferences.product_tips
      WHEN 'feature_updates' THEN v_preferences.feature_updates
      WHEN 'marketing_communications' THEN v_preferences.marketing_communications
      WHEN 'weekly_summaries' THEN v_preferences.weekly_summaries
      ELSE true
    END;
  ELSIF v_category IN ('security_notifications','billing_notifications') THEN
    v_allowed := true;
  END IF;

  IF NOT v_allowed THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'preference_disabled');
  END IF;

  IF NOT check_frequency_limit(p_user_id) THEN
    RETURN jsonb_build_object('success', true, 'skipped', true, 'reason', 'frequency_limit');
  END IF;

  CASE v_action_type
    WHEN 'in_app_notification' THEN
      INSERT INTO public.user_notifications (customer_profile_id, notification_type, title, message, link, metadata, read, created_at)
      VALUES (
        v_profile.id,
        COALESCE(v_category, 'automation'),
        p_action->>'title',
        p_action->>'message',
        p_action->>'link',
        p_action->'metadata',
        false,
        now()
      );
    WHEN 'dashboard_announcement' THEN
      INSERT INTO public.feature_announcements (title, description, cta_text, cta_url, target_segments, priority, enabled, start_date, end_date, created_at)
      VALUES (
        p_action->>'title',
        p_action->>'message',
        p_action->>'cta_text',
        p_action->>'link',
        p_action->'target_segments',
        COALESCE((p_action->>'priority')::int, 1),
        true,
        now(),
        now() + interval '30 days',
        now()
      );
    WHEN 'add_tag' THEN
      SELECT id INTO v_tag_id FROM public.customer_tags WHERE name = p_action->>'value' LIMIT 1;
      IF v_tag_id IS NULL THEN
        INSERT INTO public.customer_tags (name, is_system, created_at)
        VALUES (p_action->>'value', false, now())
        RETURNING id INTO v_tag_id;
      END IF;
      INSERT INTO public.customer_tag_assignments (customer_profile_id, tag_id, assigned_by, created_at)
      VALUES (v_profile.id, v_tag_id, 'automation', now())
      ON CONFLICT DO NOTHING;
    WHEN 'remove_tag' THEN
      DELETE FROM public.customer_tag_assignments
      WHERE customer_profile_id = v_profile.id
        AND tag_id = (SELECT id FROM public.customer_tags WHERE name = p_action->>'value' LIMIT 1);
    WHEN 'add_to_segment' THEN
      SELECT id INTO v_segment_id FROM public.customer_segments WHERE name = p_action->>'value' LIMIT 1;
      IF v_segment_id IS NOT NULL THEN
        INSERT INTO public.customer_segment_memberships (customer_profile_id, segment_id, created_at)
        VALUES (v_profile.id, v_segment_id, now())
        ON CONFLICT DO NOTHING;
      END IF;
    WHEN 'remove_from_segment' THEN
      DELETE FROM public.customer_segment_memberships
      WHERE customer_profile_id = v_profile.id
        AND segment_id = (SELECT id FROM public.customer_segments WHERE name = p_action->>'value' LIMIT 1);
    WHEN 'update_lifecycle_stage' THEN
      UPDATE public.customer_profiles
      SET lifecycle_stage = p_action->>'value',
          previous_stage = lifecycle_stage,
          stage_updated_at = now()
      WHERE id = v_profile.id;
    WHEN 'mark_milestone' THEN
      INSERT INTO public.user_milestones (customer_profile_id, milestone_key, unlocked_at)
      VALUES (v_profile.id, p_action->>'value', now())
      ON CONFLICT (customer_profile_id, milestone_key) DO NOTHING;
    WHEN 'recommendation' THEN
      INSERT INTO public.user_recommendations (user_id, recommendation_key, context, created_at)
      VALUES (p_user_id, p_action->>'value', p_action->'context', now());
    WHEN 'admin_notification' THEN
      INSERT INTO public.admin_user_notes (user_id, admin_id, note, created_at)
      VALUES (p_user_id, null, p_action->>'message', now());
    WHEN 'internal_note' THEN
      INSERT INTO public.admin_user_notes (user_id, admin_id, note, created_at)
      VALUES (p_user_id, null, p_action->>'message', now());
    WHEN 'webhook' THEN
      v_result := jsonb_build_object('success', true, 'queued', true, 'url', p_action->>'url');
    ELSE
      v_result := jsonb_build_object('success', true, 'noop', true);
  END CASE;

  RETURN v_result;
END;
$$;


--
-- Name: expire_organization_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."expire_organization_invitations"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  UPDATE public.organization_invitations
  SET status = 'expired'::invitation_status
  WHERE status IN ('pending','delivered','opened','resent') AND expires_at < now();
END;
$$;


--
-- Name: finalize_credit_reservation("uuid", "text", "jsonb", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."finalize_credit_reservation"("p_reservation_id" "uuid" DEFAULT NULL::"uuid", "p_outcome" "text" DEFAULT 'success'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_error_reason" "text" DEFAULT NULL::"text", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_role TEXT := COALESCE(current_setting('role', true), 'anon');
  v_auth_uid UUID := auth.uid();
  v_res RECORD;
BEGIN
  SELECT * INTO v_res FROM public.credit_reservations WHERE id = p_reservation_id FOR UPDATE;

  IF v_res IS NULL OR v_res.status NOT IN ('reserved', 'pending') THEN
    RETURN false;
  END IF;

  -- Caller authorization
  IF v_role = 'service_role' THEN
    NULL;
  ELSIF v_auth_uid IS NOT NULL THEN
    IF v_res.user_id IS NOT NULL AND v_res.user_id <> v_auth_uid THEN
      RAISE EXCEPTION 'Not authorized to settle this reservation';
    END IF;
  ELSE
    IF v_res.user_id IS NOT NULL THEN
      RAISE EXCEPTION 'Not authorized to settle this reservation';
    END IF;
  END IF;

  IF p_outcome = 'success' THEN
    -- Deduction already happened at reserve time; settle the ledger.
    IF v_res.reservation_type = 'trial_check' THEN
      INSERT INTO public.usage_ledger (
        user_id, guest_id, feature_slug, operation, credits_amount, trial_checks_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.guest_id, v_res.feature_slug, 'trial_check_settled', 0, 1,
        'success', p_reservation_id, 'trial', p_metadata
      );
    ELSIF v_res.reservation_type = 'team_credit' AND v_res.team_owner_id IS NOT NULL THEN
      INSERT INTO public.usage_ledger (
        user_id, team_owner_id, feature_slug, operation, credits_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.team_owner_id, v_res.feature_slug, 'team_credit_deducted', COALESCE(v_res.credits_reserved, 0),
        'success', p_reservation_id, 'team', p_metadata
      );
    ELSE
      INSERT INTO public.usage_ledger (
        user_id, feature_slug, operation, credits_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.feature_slug, 'credit_deducted', COALESCE(v_res.credits_reserved, 0),
        'success', p_reservation_id, 'usage', p_metadata
      );
    END IF;

    UPDATE public.credit_reservations
    SET status = 'committed', finalized_at = now()
    WHERE id = p_reservation_id;
  ELSE
    -- GENUINE FAILURE: restore what was deducted at reserve time.
    IF v_res.reservation_type = 'trial_check' THEN
      IF v_res.user_id IS NOT NULL THEN
        UPDATE public.profiles
        SET trial_checks_remaining = LEAST(COALESCE(trial_checks_total, 5), COALESCE(trial_checks_remaining, 0) + 1),
            trial_checks_used = GREATEST(0, COALESCE(trial_checks_used, 0) - 1),
            updated_at = now()
        WHERE id = v_res.user_id;
      ELSIF v_res.guest_id IS NOT NULL THEN
        UPDATE public.server_guest_sessions
        SET trial_checks_remaining = LEAST(COALESCE(trial_checks_total, 1), COALESCE(trial_checks_remaining, 0) + 1),
            trial_checks_used = GREATEST(0, COALESCE(trial_checks_used, 0) - 1),
            updated_at = now()
        WHERE guest_id = v_res.guest_id;
      END IF;
    ELSIF v_res.reservation_type = 'team_credit' AND v_res.team_allocation_id IS NOT NULL THEN
      UPDATE public.team_credit_allocations
      SET used_credits = GREATEST(0, used_credits - COALESCE(v_res.credits_reserved, 0)),
          updated_at = now()
      WHERE id = v_res.team_allocation_id;
    ELSE
      UPDATE public.profiles
      SET credits_balance = COALESCE(credits_balance, 0) + COALESCE(v_res.credits_reserved, 0),
          updated_at = now()
      WHERE id = v_res.user_id;
    END IF;

    UPDATE public.credit_reservations
    SET status = 'released', finalized_at = now()
    WHERE id = p_reservation_id;

    INSERT INTO public.usage_ledger (
      user_id, guest_id, team_owner_id, feature_slug, operation, credits_amount,
      outcome, reservation_id, error_reason, ledger_type, metadata
    ) VALUES (
      v_res.user_id, v_res.guest_id, v_res.team_owner_id, v_res.feature_slug, 'reservation_released',
      COALESCE(v_res.credits_reserved, 0), 'failed', p_reservation_id, p_error_reason, 'refund', p_metadata
    );
  END IF;

  RETURN true;
END;
$$;


--
-- Name: generate_referral_code(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."generate_referral_code"() RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  code text;
BEGIN
  LOOP
    code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));
    IF NOT EXISTS (SELECT 1 FROM public.referral_links WHERE code = code) THEN
      RETURN code;
    END IF;
  END LOOP;
END;
$$;


--
-- Name: generate_unique_referral_code_for_user(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."generate_unique_referral_code_for_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.referral_code IS NULL THEN
    LOOP
      NEW.referral_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 8));
      IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE referral_code = NEW.referral_code AND id <> NEW.id) THEN
        RETURN NEW;
      END IF;
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: get_activation_funnel(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_activation_funnel"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'stages', jsonb_build_array(
      jsonb_build_object('stage_key','visitors','label','Visitors','count', (SELECT COUNT(DISTINCT id) FROM anonymous_visitors)),
      jsonb_build_object('stage_key','signups','label','Signups','count', (SELECT COUNT(*) FROM customer_profiles)),
      jsonb_build_object('stage_key','verified','label','Email Verified','count', (SELECT COUNT(*) FROM customer_profiles WHERE email_verified = true)),
      jsonb_build_object('stage_key','first_scan','label','First Scan','count', (SELECT COUNT(DISTINCT customer_profile_id) FROM user_checklist_progress WHERE item_key = 'first_scan' AND completed = true)),
      jsonb_build_object('stage_key','second_tool','label','Second Tool','count', (SELECT COUNT(*) FROM (SELECT customer_profile_id FROM user_checklist_progress WHERE completed = true AND item_key IN ('first_humanize','first_plagiarism','first_api_key','install_extension','install_plugin') GROUP BY customer_profile_id HAVING COUNT(*) >= 2) t)),
      jsonb_build_object('stage_key','extension_install','label','Extension Install','count', (SELECT COUNT(DISTINCT customer_profile_id) FROM user_checklist_progress WHERE item_key = 'install_extension' AND completed = true)),
      jsonb_build_object('stage_key','pricing_visit','label','Pricing Visit','count', (SELECT COUNT(DISTINCT customer_profile_id) FROM user_journey_stages WHERE stage_key = 'pricing_visit' AND completed = true)),
      jsonb_build_object('stage_key','upgrade','label','Upgraded','count', (SELECT COUNT(*) FROM customer_profiles WHERE subscription_plan IS NOT NULL AND subscription_plan <> 'free')),
      jsonb_build_object('stage_key','retained','label','Retained (30d)','count', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE created_at > now() - interval '30 days'))
    )
  ) INTO result;
  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_auth_user_id_by_email("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_auth_user_id_by_email"("p_email" "text") RETURNS TABLE("id" "uuid", "email_confirmed_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  return query select au.id, au.email_confirmed_at from auth.users au where au.email = p_email;
end;
$$;


--
-- Name: get_automation_analytics("uuid", "date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_automation_analytics"("p_workflow_id" "uuid" DEFAULT NULL::"uuid", "p_start_date" "date" DEFAULT (("now"() - '30 days'::interval))::"date", "p_end_date" "date" DEFAULT ("now"())::"date") RETURNS TABLE("workflow_id" "uuid", "workflow_name" "text", "date" "date", "starts" integer, "completions" integer, "failures" integer, "conversion_count" integer, "email_delivered" integer, "email_opened" integer, "email_clicked" integer, "notification_count" integer, "recommendation_click" integer, "unique_user_count" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT
    a.workflow_id,
    w.name AS workflow_name,
    a.date,
    a.starts,
    a.completions,
    a.failures,
    a.conversion_count,
    a.email_delivered,
    a.email_opened,
    a.email_clicked,
    a.notification_count,
    a.recommendation_click,
    a.unique_user_count
  FROM automation_analytics a
  JOIN automation_workflows w ON w.id = a.workflow_id
  WHERE a.date BETWEEN p_start_date AND p_end_date
    AND (p_workflow_id IS NULL OR a.workflow_id = p_workflow_id)
  ORDER BY a.date DESC, w.name;
$$;


--
-- Name: get_customer_overview_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_customer_overview_stats"() RETURNS "jsonb"
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT jsonb_build_object(
    'total_profiles', (SELECT count(*) FROM customer_profiles WHERE is_anonymized = false),
    'anonymous_profiles', (SELECT count(*) FROM customer_profiles WHERE user_id IS NULL AND is_anonymized = false),
    'registered_profiles', (SELECT count(*) FROM customer_profiles WHERE user_id IS NOT NULL AND is_anonymized = false),
    'active_today', (SELECT count(*) FROM customer_profiles WHERE updated_at >= now() - interval '1 day' AND is_anonymized = false),
    'active_this_week', (SELECT count(*) FROM customer_profiles WHERE updated_at >= now() - interval '7 days' AND is_anonymized = false),
    'pro_users', (SELECT count(*) FROM customer_profiles WHERE subscription_plan IN ('pro','business','enterprise') AND is_anonymized = false),
    'churn_risk', (SELECT count(*) FROM customer_profiles WHERE lead_status = 'churn_risk' AND is_anonymized = false)
  );
$$;


--
-- Name: get_effective_plan("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_effective_plan"("p_user_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_plan text;
  v_org_plan text;
BEGIN
  SELECT COALESCE(subscription_plan, 'free') INTO v_user_plan
  FROM public.profiles
  WHERE id = p_user_id;

  IF v_user_plan IS NULL THEN v_user_plan := 'free'; END IF;

  SELECT o.plan INTO v_org_plan
  FROM public.organization_members om
  JOIN public.organizations o ON om.organization_id = o.id
  WHERE om.user_id = p_user_id AND o.status = 'active'
  LIMIT 1;

  IF v_org_plan = 'enterprise' THEN
    RETURN 'enterprise';
  END IF;

  RETURN v_user_plan;
END;
$$;


--
-- Name: get_enterprise_dashboard_metrics("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_enterprise_dashboard_metrics"("p_org_id" "uuid") RETURNS "public"."enterprise_dashboard_metrics"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result public.enterprise_dashboard_metrics;
BEGIN
  SELECT
    COALESCE((SELECT count(*) FROM public.organization_members WHERE organization_id = p_org_id AND status = 'active'), 0),
    COALESCE((SELECT count(*) FROM public.organization_members m
      JOIN public.profiles p ON p.id = m.user_id
      WHERE m.organization_id = p_org_id AND m.status = 'active' AND p.last_login_at > now() - interval '30 days'), 0),
    COALESCE((SELECT count(*) FROM public.organization_invitations
      WHERE organization_id = p_org_id AND status IN ('pending','delivered','opened','resent')), 0),
    COALESCE((SELECT count(*) FROM public.departments WHERE organization_id = p_org_id), 0),
    COALESCE((SELECT count(*) FROM public.teams WHERE organization_id = p_org_id), 0),
    COALESCE((SELECT count(*) FROM public.workspaces WHERE organization_id = p_org_id), 0),
    COALESCE((SELECT count(*) FROM public.api_usage_logs u
      JOIN public.organization_members m ON m.user_id = u.user_id
      WHERE m.organization_id = p_org_id AND u.created_at > now() - interval '30 days'), 0),
    COALESCE((SELECT count(*) FROM public.organization_members
      WHERE organization_id = p_org_id AND status = 'active' AND joined_at >= date_trunc('month', now())), 0),
    COALESCE((SELECT count(*) FROM storage.objects so
      JOIN public.organization_members m ON m.user_id = so.owner::uuid
      WHERE m.organization_id = p_org_id), 0),
    COALESCE((SELECT sum(((so.metadata->>'size')::bigint)) FROM storage.objects so
      JOIN public.organization_members m ON m.user_id = so.owner::uuid
      WHERE m.organization_id = p_org_id AND so.metadata ? 'size'), 0),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object('email', sub.email, 'display_name', COALESCE(sub.full_name, ''), 'last_login_at', sub.last_login_at))
      FROM (
        SELECT p.email, p.full_name, p.last_login_at
        FROM public.organization_members m
        JOIN public.profiles p ON p.id = m.user_id
        WHERE m.organization_id = p_org_id AND m.status = 'active'
        ORDER BY p.last_login_at DESC NULLS LAST LIMIT 10
      ) sub
    ), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object('event_type', sub.event_type, 'severity', sub.severity, 'detected_at', sub.detected_at, 'details', sub.details))
      FROM (
        SELECT se.event_type, se.severity, se.detected_at, se.details
        FROM public.security_events se
        WHERE se.organization_id = p_org_id
        ORDER BY se.detected_at DESC LIMIT 5
      ) sub
    ), '[]'::jsonb),
    COALESCE((
      SELECT jsonb_agg(jsonb_build_object('action', sub.action, 'resource_type', sub.resource_type, 'metadata', sub.metadata, 'created_at', sub.created_at, 'email', sub.email, 'display_name', COALESCE(sub.full_name, '')))
      FROM (
        SELECT af.action, af.resource_type, af.metadata, af.created_at, p.email, p.full_name
        FROM public.activity_feeds af
        LEFT JOIN public.profiles p ON p.id = af.user_id
        WHERE af.organization_id = p_org_id
        ORDER BY af.created_at DESC LIMIT 10
      ) sub
    ), '[]'::jsonb)
  INTO v_result;

  RETURN v_result;
END;
$$;


