$$;


--
-- Name: get_feature_adoption_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_feature_adoption_stats"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'features', jsonb_build_array(
      jsonb_build_object('feature_key','detector','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'detector'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'detector' AND created_at > now() - interval '7 days')),
      jsonb_build_object('feature_key','humanizer','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'humanizer'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'humanizer' AND created_at > now() - interval '7 days')),
      jsonb_build_object('feature_key','plagiarism','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'plagiarism'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'plagiarism' AND created_at > now() - interval '7 days')),
      jsonb_build_object('feature_key','api','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'api_key_created'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'api_key_created' AND created_at > now() - interval '7 days')),
      jsonb_build_object('feature_key','extension','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'chrome_extension_install'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'chrome_extension_install' AND created_at > now() - interval '7 days')),
      jsonb_build_object('feature_key','plugin','total_users', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'wordpress_plugin_install'), 'active_users_week', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE event_type = 'tool_used' AND metadata->>'tool' = 'wordpress_plugin_install' AND created_at > now() - interval '7 days'))
    )
  ) INTO result;
  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_feature_remaining("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_feature_remaining"("p_user_id" "uuid", "p_feature_slug" "text", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS TABLE("remaining" bigint, "limit_value" bigint, "plan" "text", "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_plan text;
  v_active boolean := false;
  v_limit integer;
  v_date date;
  v_used bigint := 0;
BEGIN
  v_user_plan := public.get_effective_plan(p_user_id);

  IF v_user_plan IN ('pro', 'business', 'enterprise') THEN
    SELECT (
      subscription_status IN ('Active', 'trialing', 'Cancelled', 'canceled')
      AND (plan_end_date IS NULL OR plan_end_date > now())
    ) INTO v_active
    FROM public.profiles
    WHERE id = p_user_id;
    IF NOT v_active THEN
      v_user_plan := 'free';
    END IF;
  END IF;

  SELECT feature_limits.daily_limit INTO v_limit
  FROM public.feature_limits
  WHERE feature_limits.feature_slug = p_feature_slug
    AND feature_limits.plan = v_user_plan;

  IF NOT FOUND THEN
    RETURN QUERY SELECT (-1)::bigint, (-1)::bigint, v_user_plan, NULL::timestamptz;
    RETURN;
  END IF;

  IF v_limit IS NULL THEN
    RETURN QUERY SELECT NULL::bigint, NULL::bigint, v_user_plan, NULL::timestamptz;
    RETURN;
  END IF;

  v_date := (current_timestamp AT TIME ZONE p_timezone)::date;

  SELECT COALESCE(used_count, 0) INTO v_used
  FROM public.user_feature_usage
  WHERE user_id = p_user_id
    AND feature_slug = p_feature_slug
    AND usage_date = v_date;

  IF NOT FOUND THEN
    v_used := 0;
  END IF;

  RETURN QUERY SELECT
    GREATEST(v_limit - v_used, 0)::bigint,
    v_limit::bigint,
    v_user_plan,
    (v_date + interval '1 day')::timestamptz;
END;
$$;


--
-- Name: get_lead_event_stats(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_lead_event_stats"() RETURNS TABLE("event_type" "text", "count" bigint)
    LANGUAGE "sql" SECURITY DEFINER
    AS $$
  SELECT event_type, COUNT(*) AS count
  FROM lead_events
  GROUP BY event_type
  ORDER BY count DESC;
$$;


--
-- Name: get_lifecycle_analytics("date", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_lifecycle_analytics"("start_date" "date" DEFAULT (("now"() - '30 days'::interval))::"date", "end_date" "date" DEFAULT ("now"())::"date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'lifecycle_distribution', (SELECT jsonb_agg(jsonb_build_object('stage', lifecycle_stage, 'count', cnt)) FROM (SELECT lifecycle_stage, COUNT(*) as cnt FROM customer_profiles WHERE lifecycle_stage IS NOT NULL GROUP BY lifecycle_stage) s),
    'activation_rate', (SELECT ROUND((COUNT(*) FILTER (WHERE activation_score >= 60)::numeric / NULLIF(COUNT(*), 0)) * 100, 2) FROM customer_profiles),
    'dau', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE created_at > now() - interval '1 day'),
    'wau', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE created_at > now() - interval '7 days'),
    'mau', (SELECT COUNT(DISTINCT customer_profile_id) FROM lead_events WHERE created_at > now() - interval '30 days'),
    'power_users', (SELECT COUNT(*) FROM customer_profiles WHERE lifecycle_stage = 'power_user'),
    'inactive_users', (SELECT COUNT(*) FROM customer_profiles WHERE lifecycle_stage IN ('inactive', 'at_risk', 'churned')),
    'at_risk_users', (SELECT COUNT(*) FROM customer_profiles WHERE lifecycle_stage = 'at_risk'),
    'average_activation_score', (SELECT ROUND(AVG(activation_score), 2) FROM customer_profiles),
    'average_health_score', (SELECT ROUND(AVG(health_score), 2) FROM customer_profiles)
  ) INTO result;
  RETURN COALESCE(result, '{}'::jsonb);
END;
$$;


--
-- Name: get_or_create_customer_profile("text", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_or_create_customer_profile"("p_visitor_id" "text" DEFAULT NULL::"text", "p_user_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_profile_id uuid;
  v_visitor anonymous_visitors%ROWTYPE;
  v_user profiles%ROWTYPE;
BEGIN
  IF p_user_id IS NOT NULL THEN
    SELECT id INTO v_profile_id FROM customer_profiles WHERE user_id = p_user_id;
    IF FOUND THEN RETURN v_profile_id; END IF;
  END IF;

  IF p_visitor_id IS NOT NULL THEN
    SELECT id INTO v_profile_id FROM customer_profiles WHERE visitor_id = p_visitor_id;
    IF FOUND THEN RETURN v_profile_id; END IF;
  END IF;

  IF p_visitor_id IS NOT NULL THEN
    SELECT * INTO v_visitor FROM anonymous_visitors WHERE visitor_id = p_visitor_id;
  END IF;

  IF p_user_id IS NOT NULL THEN
    SELECT * INTO v_user FROM profiles WHERE id = p_user_id;
  END IF;

  INSERT INTO customer_profiles (
    user_id, visitor_id, email, full_name, username, role, country, language,
    first_landing_page, first_referrer, first_channel,
    first_utm_source, first_utm_medium, first_utm_campaign, first_utm_content, first_utm_term,
    last_referrer, last_channel,
    last_utm_source, last_utm_medium, last_utm_campaign, last_utm_content, last_utm_term,
    signup_at, last_login_at, session_count, subscription_plan, account_status, subscription_status
  ) VALUES (
    p_user_id,
    p_visitor_id,
    COALESCE(v_user.email, NULL),
    COALESCE(v_user.full_name, NULL),
    COALESCE(v_user.email, NULL),
    COALESCE(v_user.role::text, 'user'),
    COALESCE(v_visitor.country, NULL),
    COALESCE(v_visitor.language, NULL),
    COALESCE(v_visitor.landing_page, NULL),
    COALESCE(v_visitor.referrer_url, NULL),
    classify_traffic_channel(v_visitor.referrer_url, v_visitor.utm_source, v_visitor.utm_medium),
    v_visitor.utm_source, v_visitor.utm_medium, v_visitor.utm_campaign, v_visitor.utm_content, v_visitor.utm_term,
    v_visitor.referrer_url,
    classify_traffic_channel(v_visitor.referrer_url, v_visitor.utm_source, v_visitor.utm_medium),
    v_visitor.utm_source, v_visitor.utm_medium, v_visitor.utm_campaign, v_visitor.utm_content, v_visitor.utm_term,
    COALESCE(v_user.created_at, NULL),
    COALESCE(v_user.last_login_date, NULL),
    COALESCE(v_visitor.session_count, 0),
    COALESCE(v_user.subscription_plan, 'free'),
    COALESCE(v_user.account_status, 'active'),
    COALESCE(v_user.subscription_status, 'active')
  )
  RETURNING id INTO v_profile_id;

  RETURN v_profile_id;
END;
$$;


--
-- Name: get_org_role("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_org_role"("p_org_id" "uuid", "p_user_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    AS $$
  SELECT role::text
  FROM public.organization_members
  WHERE organization_id = p_org_id AND user_id = p_user_id AND status = 'active'
  LIMIT 1;
$$;


--
-- Name: get_organization_analytics("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_organization_analytics"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'workspace_count', (SELECT COUNT(*) FROM public.workspaces WHERE organization_id = p_org_id AND status = 'active'),
    'member_count', (SELECT COUNT(*) FROM public.organization_members WHERE organization_id = p_org_id AND status = 'active'),
    'report_count', (SELECT COUNT(*) FROM public.collaboration_reports r JOIN public.workspaces w ON r.workspace_id = w.id WHERE w.organization_id = p_org_id AND r.status = 'active'),
    'project_count', (SELECT COUNT(*) FROM public.workspace_projects p JOIN public.workspaces w ON p.workspace_id = w.id WHERE w.organization_id = p_org_id AND p.status = 'active'),
    'api_used', COALESCE((SELECT SUM(used) FROM public.workspace_api_quotas q JOIN public.workspaces w ON q.workspace_id = w.id WHERE w.organization_id = p_org_id), 0),
    'api_quota', COALESCE((SELECT SUM(quota) FROM public.workspace_api_quotas q JOIN public.workspaces w ON q.workspace_id = w.id WHERE w.organization_id = p_org_id), 0)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: get_organization_dashboard_summary("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_organization_dashboard_summary"("p_org_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_org jsonb;
  v_metrics public.enterprise_dashboard_metrics;
  v_owner jsonb;
  v_billing jsonb;

  v_total_members bigint;
  v_active_users_30d bigint;
  v_mfa_enabled_count bigint;

  v_failed_logins bigint;
  v_suspicious_logins bigint;
  v_password_resets bigint;
  v_role_changes bigint;
  v_api_key_creations bigint;
  v_invitation_abuse bigint;
  v_open_alerts bigint;

  v_security_score int;
  v_seats_total int;

  v_api_quota bigint;
  v_api_used bigint;
  v_storage_quota bigint;

  v_start_date timestamptz;
BEGIN
  v_start_date := date_trunc('day', now() - interval '29 days');

  SELECT jsonb_build_object(
    'id', o.id,
    'name', o.name,
    'logo_url', o.logo_url,
    'plan', o.plan,
    'status', o.status,
    'created_at', o.created_at,
    'owner_id', o.owner_id,
    'max_members', o.max_members,
    'mfa_required', o.mfa_required
  ) INTO v_org
  FROM public.organizations o
  WHERE o.id = p_org_id;

  SELECT * INTO v_metrics FROM public.get_enterprise_dashboard_metrics(p_org_id);

  SELECT jsonb_build_object(
    'id', p.id,
    'display_name', COALESCE(p.display_name, p.full_name, ''),
    'email', p.email,
    'avatar_url', p.avatar_url
  ) INTO v_owner
  FROM public.profiles p
  WHERE p.id = (v_org->>'owner_id')::uuid;

  SELECT jsonb_build_object(
    'plan', b.plan,
    'status', b.status,
    'next_billing_date', b.next_billing_date
  ) INTO v_billing
  FROM public.organization_billing b
  WHERE b.organization_id = p_org_id;

  SELECT count(*) FILTER (WHERE m.status = 'active'),
         count(*) FILTER (WHERE m.status = 'active' AND p.last_login_at > now() - interval '30 days')
  INTO v_total_members, v_active_users_30d
  FROM public.organization_members m
  JOIN public.profiles p ON p.id = m.user_id
  WHERE m.organization_id = p_org_id;

  SELECT count(*) INTO v_mfa_enabled_count
  FROM public.organization_members m
  JOIN public.profiles p ON p.id = m.user_id
  WHERE m.organization_id = p_org_id AND m.status = 'active' AND p.mfa_enabled = true;

  SELECT count(*) FILTER (WHERE event_type = 'login_failure'),
         count(*) FILTER (WHERE event_type = 'suspicious_login'),
         count(*) FILTER (WHERE event_type = 'password_changed'),
         count(*) FILTER (WHERE event_type = 'permission_changed'),
         count(*) FILTER (WHERE event_type = 'api_key_created'),
         count(*) FILTER (WHERE event_type = 'invitation_abuse')
  INTO v_failed_logins, v_suspicious_logins, v_password_resets, v_role_changes, v_api_key_creations, v_invitation_abuse
  FROM public.security_events
  WHERE organization_id = p_org_id AND detected_at > now() - interval '30 days';

  SELECT count(*) INTO v_open_alerts
  FROM public.security_alerts
  WHERE organization_id = p_org_id AND status = 'open';

  v_seats_total := COALESCE((v_org->>'max_members')::int, 10);

  v_security_score := 100;
  IF v_total_members > 0 THEN
    v_security_score := v_security_score - ((v_total_members - v_mfa_enabled_count) * 20 / v_total_members);
  END IF;
  v_security_score := v_security_score
    - LEAST(v_failed_logins * 2, 20)
    - LEAST(v_suspicious_logins * 5, 25)
    - LEAST(v_open_alerts * 5, 20)
    - LEAST(v_invitation_abuse * 10, 20);
  IF v_security_score < 0 THEN v_security_score := 0; END IF;
  IF v_security_score > 100 THEN v_security_score := 100; END IF;

  SELECT COALESCE(SUM(q.quota), 0), COALESCE(SUM(q.used), 0)
  INTO v_api_quota, v_api_used
  FROM public.workspace_api_quotas q
  JOIN public.workspaces w ON q.workspace_id = w.id
  WHERE w.organization_id = p_org_id;

  v_storage_quota := public.organization_storage_quota(v_org->>'plan');

  RETURN jsonb_build_object(
    'organization', v_org,
    'owner', v_owner,
    'billing', v_billing,
    'metrics', to_jsonb(v_metrics),

    'total_members', v_total_members,
    'active_users_30d', v_active_users_30d,
    'pending_invitations', (v_metrics).pending_invitations,
    'departments_count', (v_metrics).departments_count,
    'teams_count', (v_metrics).teams_count,
    'workspaces_count', (v_metrics).workspaces_count,
    'api_calls_30d', (v_metrics).api_calls_30d,
    'api_quota', v_api_quota,
    'api_used', v_api_used,
    'storage_bytes', (v_metrics).storage_bytes,
    'storage_quota', v_storage_quota,
    'new_members_this_month', (v_metrics).new_members_this_month,
    'seats_used', v_total_members,
    'seats_total', v_seats_total,

    'security_score', v_security_score,
    'mfa_adoption', jsonb_build_object('enabled', v_mfa_enabled_count, 'total', v_total_members),
    'failed_logins_30d', v_failed_logins,
    'suspicious_logins_30d', v_suspicious_logins,
    'password_resets_30d', v_password_resets,
    'role_changes_30d', v_role_changes,
    'api_key_creations_30d', v_api_key_creations,
    'invitation_abuse_30d', v_invitation_abuse,
    'open_security_alerts', v_open_alerts,

    'recent_logins', (v_metrics).recent_logins,
    'recent_security_events', (v_metrics).recent_security_events,
    'recent_activity', (v_metrics).recent_activity,

    'charts', jsonb_build_object(
      'member_growth', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'members', c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT count(*)::int c
          FROM public.organization_members
          WHERE organization_id = p_org_id AND status = 'active' AND joined_at <= d
        ) m ON true
      ),
      'api_usage', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'calls', c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT count(*)::int c
          FROM public.api_usage_logs u
          JOIN public.organization_members m ON m.user_id = u.user_id
          WHERE m.organization_id = p_org_id AND date_trunc('day', u.created_at) = d
        ) u ON true
      ),
      'login_activity', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'logins', c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT count(*)::int c
          FROM public.login_history lh
          JOIN public.organization_members m ON m.user_id = lh.user_id AND m.organization_id = p_org_id
          WHERE lh.success = true AND date_trunc('day', lh.created_at) = d
        ) l ON true
      ),
      'workspace_growth', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'workspaces', c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT count(*)::int c
          FROM public.workspaces
          WHERE organization_id = p_org_id AND status = 'active' AND created_at <= d
        ) w ON true
      ),
      'storage_growth', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'bytes', c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT COALESCE(SUM(((so.metadata->>'size')::bigint)), 0)::bigint c
          FROM storage.objects so
          JOIN public.organization_members m ON m.user_id = so.owner::uuid
          WHERE m.organization_id = p_org_id AND so.metadata ? 'size' AND so.created_at <= d
        ) s ON true
      ),
      'invitations', (
        SELECT coalesce(jsonb_agg(jsonb_build_object('date', d::date, 'sent', s.c, 'accepted', a.c) ORDER BY d), '[]'::jsonb)
        FROM generate_series(v_start_date, now(), interval '1 day') d
        LEFT JOIN LATERAL (
          SELECT count(*)::int c FROM public.organization_invitations
          WHERE organization_id = p_org_id AND date_trunc('day', created_at) = d
        ) s ON true
        LEFT JOIN LATERAL (
          SELECT count(*)::int c FROM public.organization_invitations
          WHERE organization_id = p_org_id AND status = 'accepted' AND date_trunc('day', accepted_at) = d
        ) a ON true
      )
    )
  );
END;
$$;


--
-- Name: get_organization_invitation_by_token("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_organization_invitation_by_token"("p_token" "text") RETURNS TABLE("id" "uuid", "organization_id" "uuid", "org_name" "text", "org_logo_url" "text", "inviter_name" "text", "inviter_email" "text", "invitee_email" "text", "role" "text", "department_id" "uuid", "department_name" "text", "team_id" "uuid", "team_name" "text", "workspace_id" "uuid", "workspace_name" "text", "message" "text", "status" "public"."invitation_status", "expires_at" timestamp with time zone, "created_at" timestamp with time zone, "accepted_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    i.id,
    i.organization_id,
    o.name,
    o.logo_url,
    COALESCE(p.full_name, p.display_name, '')::text,
    p.email::text,
    i.email,
    i.role::text,
    i.department_id,
    d.name,
    i.team_id,
    t.name,
    i.workspace_id,
    w.name,
    i.message,
    i.status,
    i.expires_at,
    i.created_at,
    i.accepted_at
  FROM public.organization_invitations i
  JOIN public.organizations o ON o.id = i.organization_id
  LEFT JOIN public.profiles p ON p.id = i.invited_by
  LEFT JOIN public.departments d ON d.id = i.department_id
  LEFT JOIN public.teams t ON t.id = i.team_id
  LEFT JOIN public.workspaces w ON w.id = i.workspace_id
  WHERE i.token = p_token;
END;
$$;


--
-- Name: get_plan_price("text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_plan_price"("p_plan" "text", "p_interval" "text") RETURNS TABLE("p_plan" "text", "p_interval" "text", "p_currency" "text", "p_amount_cents" integer, "p_credits" integer)
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT plan, billing_interval, currency, amount_cents, credits
  FROM public.plan_prices
  WHERE lower(plan) = lower(p_plan)
    AND lower(billing_interval) = lower(p_interval)
    AND is_active = true;
$$;


--
-- Name: get_team_credit_summary("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_team_credit_summary"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_plan text;
  v_credits_balance integer;
  v_user_email text;
  v_is_owner boolean := false;
  v_allocations jsonb := '[]'::jsonb;
  v_member_allocation record;
  v_total_allocated integer := 0;
  v_total_consumed integer := 0;
BEGIN
  SELECT email, subscription_plan, COALESCE(credits_balance, 0)
  INTO v_user_email, v_plan, v_credits_balance
  FROM public.profiles
  WHERE id = p_user_id;

  IF v_plan IN ('business', 'enterprise') THEN
    v_is_owner := true;
  END IF;

  -- If user is owner
  IF v_is_owner THEN
    SELECT
      COALESCE(SUM(allocated_credits), 0),
      COALESCE(SUM(consumed_credits), 0),
      COALESCE(jsonb_agg(to_jsonb(t.*) ORDER BY t.created_at ASC), '[]'::jsonb)
    INTO v_total_allocated, v_total_consumed, v_allocations
    FROM public.team_credit_allocations t
    WHERE t.owner_id = p_user_id AND t.status != 'removed';

    RETURN jsonb_build_object(
      'is_team_account', true,
      'is_owner', true,
      'plan', v_plan,
      'total_pool', v_credits_balance,
      'total_allocated', v_total_allocated,
      'total_consumed', v_total_consumed,
      'unallocated_pool', GREATEST(0, v_credits_balance - v_total_allocated),
      'allocations', v_allocations
    );
  END IF;

  -- Check if user is a member under another owner
  SELECT t.*, p.subscription_plan as owner_plan, p.credits_balance as owner_pool
  INTO v_member_allocation
  FROM public.team_credit_allocations t
  JOIN public.profiles p ON p.id = t.owner_id
  WHERE (t.member_user_id = p_user_id OR lower(t.member_email) = lower(v_user_email))
    AND t.status = 'active'
  LIMIT 1;

  IF v_member_allocation.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'is_team_account', true,
      'is_owner', false,
      'owner_id', v_member_allocation.owner_id,
      'seat_name', v_member_allocation.seat_name,
      'role', v_member_allocation.role,
      'allocated_credits', v_member_allocation.allocated_credits,
      'consumed_credits', v_member_allocation.consumed_credits,
      'remaining_credits', GREATEST(0, v_member_allocation.allocated_credits - v_member_allocation.consumed_credits),
      'owner_shared_pool', v_member_allocation.owner_pool,
      'plan', v_member_allocation.owner_plan
    );
  END IF;

  RETURN jsonb_build_object(
    'is_team_account', false,
    'is_owner', false,
    'plan', COALESCE(v_plan, 'free'),
    'credits_balance', v_credits_balance
  );
END;
$$;


--
-- Name: get_usage_stats("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."get_usage_stats"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_user_id uuid;
  v_ai_scans integer := 0;
  v_words_analyzed integer := 0;
  v_words_humanized integer := 0;
  v_reports_generated integer := 0;
  v_plagiarism_checks integer := 0;
  v_api_requests integer := 0;
  v_extension_usage integer := 0;
  v_plugin_activity integer := 0;
  v_time_saved integer := 0;
  v_docs_processed integer := 0;
BEGIN
  SELECT user_id INTO v_user_id FROM public.customer_profiles WHERE id = p_profile_id;
  IF v_user_id IS NULL THEN
    SELECT id INTO v_user_id FROM public.profiles WHERE id = p_profile_id;
  END IF;

  IF v_user_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_ai_scans FROM public.usage_ledger WHERE user_id = v_user_id AND outcome = 'success';
    v_docs_processed := v_ai_scans;
    v_words_analyzed := v_ai_scans * 450;
    v_time_saved := v_ai_scans * 3;
  END IF;

  RETURN jsonb_build_object(
    'ai_scans', v_ai_scans,
    'words_analyzed', v_words_analyzed,
    'words_humanized', v_words_humanized,
    'reports_generated', v_reports_generated,
    'plagiarism_checks', v_plagiarism_checks,
    'api_requests', v_api_requests,
    'extension_usage', v_extension_usage,
    'plugin_activity', v_plugin_activity,
    'time_saved_minutes', v_time_saved,
    'documents_processed', v_docs_processed
  );
END;
$$;


SET default_tablespace = '';

SET default_table_access_method = "heap";

--
-- Name: communication_preferences; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE IF NOT EXISTS "public"."communication_preferences" (
    "user_id" "uuid" NOT NULL,
    "product_tips" boolean DEFAULT true NOT NULL,
    "feature_updates" boolean DEFAULT true NOT NULL,
    "security_notifications" boolean DEFAULT true NOT NULL,
    "billing_notifications" boolean DEFAULT true NOT NULL,
    "marketing_communications" boolean DEFAULT true NOT NULL,
    "weekly_summaries" boolean DEFAULT true NOT NULL,
    "email_enabled" boolean DEFAULT true NOT NULL,
    "in_app_enabled" boolean DEFAULT true NOT NULL,
    "dashboard_announcements_enabled" boolean DEFAULT true NOT NULL,
    "max_messages_per_day" integer DEFAULT 5 NOT NULL,
    "timezone" "text" DEFAULT 'UTC'::"text",
    "quiet_hours_start" time without time zone DEFAULT '22:00:00'::time without time zone,
    "quiet_hours_end" time without time zone DEFAULT '08:00:00'::time without time zone,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "communication_preferences_max_messages_check" CHECK ((("max_messages_per_day" >= 1) AND ("max_messages_per_day" <= 100)))
);


