--

CREATE OR REPLACE FUNCTION "public"."increment_api_key_usage"("key_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE api_keys
  SET
