--
-- Name: increment_feature_usage("uuid", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."increment_feature_usage"("p_user_id" "uuid", "p_feature_slug" "text", "p_timezone" "text" DEFAULT 'UTC'::"text") RETURNS TABLE("remaining" bigint, "limit_value" bigint, "used" bigint, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_role TEXT := COALESCE(current_setting('role', true), 'anon');
  v_auth_uid UUID := auth.uid();
  v_profile RECORD;
BEGIN
  IF v_role <> 'service_role' THEN
    IF v_auth_uid IS NOT NULL THEN
      IF p_user_id IS NOT NULL AND p_user_id <> v_auth_uid THEN
        RAISE EXCEPTION 'Not authorized';
      END IF;
      p_user_id := v_auth_uid;
    ELSE
      p_user_id := NULL;
    END IF;
  END IF;

  IF p_user_id IS NULL THEN
    RETURN QUERY SELECT 0::bigint, 1::bigint, 1::bigint, NULL::timestamptz;
    RETURN;
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, NULL::timestamptz;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    GREATEST(COALESCE(v_profile.trial_checks_remaining, 0), COALESCE(v_profile.credits_balance, 0))::bigint,
    COALESCE(v_profile.trial_checks_total, 5)::bigint,
    COALESCE(v_profile.trial_checks_used, 0)::bigint,
    NULL::timestamptz;
END;
$$;


--
-- Name: increment_feature_usage("uuid", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."increment_feature_usage"("p_user_id" "uuid", "p_feature_slug" "text", "p_timezone" "text" DEFAULT 'UTC'::"text", "p_count" integer DEFAULT 1) RETURNS TABLE("remaining" bigint, "limit_value" bigint, "used" bigint, "reset_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_role TEXT := COALESCE(current_setting('role', true), 'anon');
  v_auth_uid UUID := auth.uid();
  v_profile RECORD;
BEGIN
  IF v_role <> 'service_role' THEN
    IF v_auth_uid IS NOT NULL THEN
      IF p_user_id IS NOT NULL AND p_user_id <> v_auth_uid THEN
        RAISE EXCEPTION 'Not authorized';
      END IF;
      p_user_id := v_auth_uid;
    ELSE
      p_user_id := NULL;
    END IF;
  END IF;

  IF p_user_id IS NULL THEN
    RETURN QUERY SELECT 0::bigint, 1::bigint, 1::bigint, NULL::timestamptz;
    RETURN;
  END IF;

  SELECT * INTO v_profile FROM public.profiles WHERE id = p_user_id;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 0::bigint, 0::bigint, 0::bigint, NULL::timestamptz;
    RETURN;
  END IF;

  RETURN QUERY SELECT
    GREATEST(COALESCE(v_profile.trial_checks_remaining, 0), COALESCE(v_profile.credits_balance, 0))::bigint,
    COALESCE(v_profile.trial_checks_total, 5)::bigint,
    COALESCE(v_profile.trial_checks_used, 0)::bigint,
    NULL::timestamptz;
END;
$$;


--
-- Name: increment_guest_usage("text", "date"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."increment_guest_usage"("p_guest_hash" "text", "p_usage_date" "date") RETURNS TABLE("used_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_used integer;
BEGIN
  INSERT INTO public.guest_usage (guest_hash, usage_date, used_count)
  VALUES (p_guest_hash, p_usage_date, 1)
  ON CONFLICT (guest_hash, usage_date)
  DO UPDATE SET used_count = public.guest_usage.used_count + 1
  RETURNING public.guest_usage.used_count INTO v_used;

  RETURN QUERY SELECT v_used;
END;
$$;


--
-- Name: increment_guest_usage("text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."increment_guest_usage"("p_guest_hash" "text", "p_usage_date" "text", "p_count" integer DEFAULT 1) RETURNS TABLE("used_count" integer, "limit_value" integer)
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN QUERY
  INSERT INTO public.guest_usage (guest_hash, usage_date, used_count)
  VALUES (p_guest_hash, p_usage_date, p_count)
  ON CONFLICT (guest_hash, usage_date)
  DO UPDATE SET used_count = public.guest_usage.used_count + p_count
  RETURNING public.guest_usage.used_count, 5 AS limit_value;
END;
$$;


--
-- Name: increment_guest_usage("text", "text", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."increment_guest_usage"("p_guest_hash" "text", "p_usage_date" "text", "p_feature_slug" "text" DEFAULT 'ai_detector'::"text", "p_count" integer DEFAULT 1) RETURNS TABLE("used_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_used integer;
BEGIN
  INSERT INTO public.guest_usage (guest_hash, usage_date, feature_slug, used_count)
  VALUES (p_guest_hash, p_usage_date::date, p_feature_slug, GREATEST(p_count, 1))
  ON CONFLICT (guest_hash, usage_date, feature_slug)
  DO UPDATE SET used_count = public.guest_usage.used_count + GREATEST(p_count, 1)
  RETURNING public.guest_usage.used_count INTO v_used;

  RETURN QUERY SELECT v_used;
END;
$$;


