--
-- Name: merge_visitor_to_customer_profile("uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."merge_visitor_to_customer_profile"("p_user_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_visitor_id text;
  v_anon_profile_id uuid;
  v_user_profile_id uuid;
BEGIN
  SELECT visitor_id INTO v_visitor_id FROM anonymous_visitors WHERE merged_user_id = p_user_id ORDER BY merged_at DESC LIMIT 1;
  IF v_visitor_id IS NULL THEN RETURN; END IF;

  SELECT id INTO v_anon_profile_id FROM customer_profiles WHERE visitor_id = v_visitor_id;
  SELECT id INTO v_user_profile_id FROM customer_profiles WHERE user_id = p_user_id;

  IF v_anon_profile_id IS NULL THEN RETURN; END IF;

  IF v_user_profile_id IS NULL THEN
    UPDATE customer_profiles SET
      user_id = p_user_id,
      visitor_id = NULL,
      email = COALESCE(email, (SELECT email FROM profiles WHERE id = p_user_id)),
      full_name = COALESCE(full_name, (SELECT full_name FROM profiles WHERE id = p_user_id)),
      username = COALESCE(username, (SELECT email FROM profiles WHERE id = p_user_id)),
      role = COALESCE(role, (SELECT role::text FROM profiles WHERE id = p_user_id), 'user'),
      signup_at = COALESCE(signup_at, now()),
      subscription_plan = COALESCE(subscription_plan, (SELECT subscription_plan FROM profiles WHERE id = p_user_id), 'free'),
      account_status = COALESCE(account_status, (SELECT account_status FROM profiles WHERE id = p_user_id), 'active'),
      subscription_status = COALESCE(subscription_status, (SELECT subscription_status FROM profiles WHERE id = p_user_id), 'active')
    WHERE id = v_anon_profile_id;
    v_user_profile_id := v_anon_profile_id;
  ELSE
    UPDATE customer_profiles SET
      page_views = customer_profiles.page_views + anon.page_views,
      cta_clicks = customer_profiles.cta_clicks + anon.cta_clicks,
      popup_conversions = customer_profiles.popup_conversions + anon.popup_conversions,
      session_count = GREATEST(customer_profiles.session_count, anon.session_count),
      first_landing_page = COALESCE(customer_profiles.first_landing_page, anon.first_landing_page),
      first_referrer = COALESCE(customer_profiles.first_referrer, anon.first_referrer),
      first_channel = COALESCE(customer_profiles.first_channel, anon.first_channel),
      first_utm_source = COALESCE(customer_profiles.first_utm_source, anon.first_utm_source),
      first_utm_medium = COALESCE(customer_profiles.first_utm_medium, anon.first_utm_medium),
      first_utm_campaign = COALESCE(customer_profiles.first_utm_campaign, anon.first_utm_campaign),
      first_utm_content = COALESCE(customer_profiles.first_utm_content, anon.first_utm_content),
      first_utm_term = COALESCE(customer_profiles.first_utm_term, anon.first_utm_term),
      updated_at = now()
    FROM (SELECT * FROM customer_profiles WHERE id = v_anon_profile_id) AS anon
    WHERE customer_profiles.id = v_user_profile_id;

    DELETE FROM customer_profiles WHERE id = v_anon_profile_id;
  END IF;

  UPDATE lead_events SET customer_profile_id = v_user_profile_id, user_id = p_user_id WHERE visitor_id = v_visitor_id;
  UPDATE customer_devices SET customer_profile_id = v_user_profile_id WHERE customer_profile_id = v_anon_profile_id;
  UPDATE customer_segment_memberships SET customer_profile_id = v_user_profile_id WHERE customer_profile_id = v_anon_profile_id;
  UPDATE customer_tag_assignments SET customer_profile_id = v_user_profile_id WHERE customer_profile_id = v_anon_profile_id;
  UPDATE customer_interests SET customer_profile_id = v_user_profile_id WHERE customer_profile_id = v_anon_profile_id;
  UPDATE privacy_consents SET customer_profile_id = v_user_profile_id WHERE customer_profile_id = v_anon_profile_id;
END;
$$;


--
-- Name: organization_storage_quota("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."organization_storage_quota"("p_plan" "text") RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN CASE lower(coalesce(p_plan, 'team'))
    WHEN 'enterprise' THEN 1099511627776::bigint
    WHEN 'business' THEN 549755813888::bigint
    WHEN 'team' THEN 10737418240::bigint
    WHEN 'personal' THEN 1073741824::bigint
    ELSE 10737418240::bigint
  END;
END;
$$;


--
-- Name: process_automation_event("text", "uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."process_automation_event"("p_event_type" "text", "p_user_id" "uuid", "p_event_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"[]
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_event_id uuid;
  v_profile public.customer_profiles%ROWTYPE;
  v_workflow automation_workflows%ROWTYPE;
  v_execution_ids uuid[] := ARRAY[]::uuid[];
  v_trigger_config jsonb;
  v_match boolean;
  v_exists integer;
  v_start_node_id text;
BEGIN
  SELECT * INTO v_profile FROM public.customer_profiles WHERE user_id = p_user_id LIMIT 1;

  INSERT INTO automation_events (event_type, user_id, customer_profile_id, event_data)
  VALUES (p_event_type, p_user_id, v_profile.id, p_event_data)
  RETURNING id INTO v_event_id;

  FOR v_workflow IN
    SELECT * FROM automation_workflows
    WHERE status = 'active' AND trigger_type = p_event_type
  LOOP
    v_trigger_config := v_workflow.trigger_config;
    v_match := true;

    IF v_trigger_config ? 'conditions' AND jsonb_array_length(v_trigger_config->'conditions') > 0 THEN
      v_match := evaluate_workflow_condition(v_trigger_config, p_user_id);
    END IF;

    IF NOT v_match THEN
      CONTINUE;
    END IF;

    SELECT COUNT(*) INTO v_exists
    FROM automation_executions
    WHERE workflow_id = v_workflow.id
      AND user_id = p_user_id
      AND trigger_event = p_event_type
      AND trigger_event_id = v_event_id;

    IF v_exists > 0 THEN
      CONTINUE;
    END IF;

    SELECT e->>'target' INTO v_start_node_id
    FROM jsonb_array_elements(v_workflow.workflow_definition->'edges') AS e
    WHERE e->>'source' = (
      SELECT n->>'id'
      FROM jsonb_array_elements(v_workflow.workflow_definition->'nodes') AS n
      WHERE n->>'type' = 'trigger'
      LIMIT 1
    )
    LIMIT 1;

    INSERT INTO automation_executions (
      workflow_id, user_id, trigger_event, trigger_event_id,
      status, current_node_id, context
    ) VALUES (
      v_workflow.id, p_user_id, p_event_type, v_event_id,
      'running', v_start_node_id,
      jsonb_build_object('event_data', p_event_data, 'started_node', v_start_node_id)
    )
    RETURNING id INTO v_execution_ids[array_length(v_execution_ids,1)+1];
  END LOOP;

  UPDATE automation_events SET processed = true WHERE id = v_event_id;

  RETURN v_execution_ids;
END;
$$;


--
-- Name: process_pending_invitations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."process_pending_invitations"() RETURNS TABLE("processed_count" integer, "failed_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_processed int := 0;
  v_failed int := 0;
  rec record;
  v_user_id uuid;
BEGIN
  FOR rec IN
    SELECT i.id, i.organization_id, i.email, i.role, i.token
    FROM public.organization_invitations i
    WHERE i.accepted_at IS NULL
      AND i.expires_at > now()
  LOOP
    SELECT id INTO v_user_id FROM auth.users WHERE email = rec.email LIMIT 1;
    IF v_user_id IS NULL THEN
      v_failed := v_failed + 1;
      CONTINUE;
    END IF;

    BEGIN
      INSERT INTO public.organization_members (organization_id, user_id, role, status)
      VALUES (rec.organization_id, v_user_id, rec.role, 'active')
      ON CONFLICT (organization_id, user_id) DO NOTHING;

      UPDATE public.organization_invitations
      SET accepted_at = now()
      WHERE id = rec.id;

      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;
  END LOOP;

  RETURN QUERY SELECT v_processed, v_failed;
END;
$$;


--
-- Name: process_subscription_refill("text", "text", "text", "text", "text", timestamp with time zone, timestamp with time zone, integer, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."process_subscription_refill"("p_provider" "text", "p_event_id" "text", "p_customer_email" "text", "p_plan_id" "text", "p_billing_cycle" "text" DEFAULT 'monthly'::"text", "p_period_start" timestamp with time zone DEFAULT "now"(), "p_period_end" timestamp with time zone DEFAULT ("now"() + '1 mon'::interval), "p_credits_amount" integer DEFAULT NULL::integer, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid;
  v_current_plan text;
  v_effective_plan text;
  v_grant_credits integer;
  v_existing_entry record;
  v_new_balance integer;
BEGIN
  -- Idempotency check in usage_ledger
  SELECT id INTO v_existing_entry
  FROM public.usage_ledger
  WHERE ledger_type = 'subscription'
    AND metadata->>'event_id' = p_event_id
  LIMIT 1;

  IF v_existing_entry.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', true,
      'idempotent_replay', true,
      'message', 'Event already processed'
    );
  END IF;

  -- Lookup user profile
  SELECT id, subscription_plan INTO v_user_id, v_current_plan
  FROM public.profiles
  WHERE lower(email) = lower(p_customer_email)
  LIMIT 1;

  IF v_user_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', format('User profile with email %s not found', p_customer_email)
    );
  END IF;

  v_effective_plan := COALESCE(p_plan_id, v_current_plan, 'pro');

  -- Authoritative plan monthly credits calculation
  IF p_credits_amount IS NOT NULL AND p_credits_amount > 0 THEN
    v_grant_credits := p_credits_amount;
  ELSE
    CASE v_effective_plan
      WHEN 'pro' THEN v_grant_credits := 300;
      WHEN 'pro_plus' THEN v_grant_credits := 1000;
      WHEN 'business' THEN v_grant_credits := 3000;
      WHEN 'enterprise' THEN v_grant_credits := 10000;
      ELSE v_grant_credits := 300;
    END CASE;
  END IF;

  -- Atomically add credits and update subscription status
  UPDATE public.profiles
  SET
    subscription_plan = v_effective_plan,
    subscription_status = 'active',
    billing_cycle = COALESCE(p_billing_cycle, 'monthly'),
    plan_start_date = COALESCE(p_period_start, now()),
    plan_end_date = COALESCE(p_period_end, now() + interval '1 month'),
    credits_refill_date = now(),
    monthly_credit_allocation = v_grant_credits,
    credits_balance = COALESCE(credits_balance, 0) + v_grant_credits,
    updated_at = now()
  WHERE id = v_user_id
  RETURNING credits_balance INTO v_new_balance;

  -- Reset consumed credits on team allocations if billing period reset for Business/Enterprise
  IF v_effective_plan IN ('business', 'enterprise') THEN
    UPDATE public.team_credit_allocations
    SET consumed_credits = 0, updated_at = now()
    WHERE owner_id = v_user_id;
  END IF;

  -- Write to usage_ledger
  INSERT INTO public.usage_ledger (
    user_id,
    feature_slug,
    operation,
    credits_amount,
    outcome,
    ledger_type,
    metadata
  )
  VALUES (
    v_user_id,
    'subscription_refill',
    format('Subscription credit grant (%s - %s)', p_provider, v_effective_plan),
    v_grant_credits,
    'success',
    'subscription',
    jsonb_build_object(
      'provider', p_provider,
      'event_id', p_event_id,
      'plan', v_effective_plan,
      'billing_cycle', p_billing_cycle,
      'granted_credits', v_grant_credits,
      'new_balance', v_new_balance,
      'period_start', p_period_start,
      'period_end', p_period_end,
      'raw_metadata', p_metadata
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'user_id', v_user_id,
    'plan', v_effective_plan,
    'granted_credits', v_grant_credits,
    'new_balance', v_new_balance
  );
END;
$$;


