--
-- Name: set_user_goal("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."set_user_goal"("p_profile_id" "uuid", "p_goal_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_target int;
BEGIN
  SELECT target INTO v_target FROM customer_goals WHERE goal_key = p_goal_key AND enabled = true;
  IF NOT FOUND THEN RETURN false; END IF;
  INSERT INTO user_goals (customer_profile_id, goal_key, progress, target)
  VALUES (p_profile_id, p_goal_key, 0, v_target)
  ON CONFLICT (customer_profile_id, goal_key) DO NOTHING;
  RETURN true;
END;
$$;


--
-- Name: settle_client_reservation("uuid", "text", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."settle_client_reservation"("p_reservation_id" "uuid", "p_outcome" "text" DEFAULT 'success'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS TABLE("settled" boolean, "refunded" boolean, "reason" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_role TEXT := COALESCE(current_setting('role', true), 'anon');
  v_auth_uid UUID := auth.uid();
  v_res RECORD;
  v_identity_key TEXT;
  v_recent_releases INT;
  v_refund_cap INT := 3;
  v_age_limit INTERVAL := interval '10 minutes';
BEGIN
  IF p_outcome NOT IN ('success', 'failed') THEN
    RETURN QUERY SELECT FALSE, FALSE, 'invalid_outcome'::TEXT;
    RETURN;
  END IF;

  SELECT * INTO v_res FROM public.credit_reservations
  WHERE id = p_reservation_id AND status IN ('reserved', 'pending')
  FOR UPDATE;

  IF NOT FOUND THEN
    -- Already settled or unknown: idempotent success no-op.
    RETURN QUERY SELECT TRUE, FALSE, 'already_settled'::TEXT;
    RETURN;
  END IF;

  -- Authorization: the caller must own the reservation.
  IF v_role <> 'service_role' THEN
    IF v_auth_uid IS NOT NULL THEN
      IF v_res.user_id IS NOT NULL AND v_res.user_id <> v_auth_uid THEN
        RETURN QUERY SELECT FALSE, FALSE, 'not_authorized'::TEXT;
        RETURN;
      END IF;
      v_identity_key := 'user:' || v_auth_uid::TEXT;
    ELSE
      IF v_res.user_id IS NOT NULL THEN
        RETURN QUERY SELECT FALSE, FALSE, 'not_authorized'::TEXT;
        RETURN;
      END IF;
      v_identity_key := 'guest:' || COALESCE(v_res.guest_id, 'unknown');
    END IF;
  ELSE
    v_identity_key := 'user:' || COALESCE(v_res.user_id::TEXT, v_res.guest_id);
  END IF;

  IF p_outcome = 'success' THEN
    -- Deduction already happened at reserve time; just settle.
    IF v_res.reservation_type = 'trial_check' THEN
      INSERT INTO public.usage_ledger (
        user_id, guest_id, feature_slug, operation, credits_amount, trial_checks_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.guest_id, v_res.feature_slug, 'trial_check_settled', 0, 1,
        'success', p_reservation_id, 'trial', p_metadata || '{"settled_by":"client"}'::jsonb
      );
    ELSE
      INSERT INTO public.usage_ledger (
        user_id, guest_id, feature_slug, operation, credits_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.guest_id, v_res.feature_slug, 'credit_deducted', COALESCE(v_res.credits_reserved, 0),
        'success', p_reservation_id, 'usage', p_metadata || '{"settled_by":"client"}'::jsonb
      );
    END IF;

    UPDATE public.credit_reservations
    SET status = 'committed', finalized_at = now()
    WHERE id = p_reservation_id;

    RETURN QUERY SELECT TRUE, FALSE, NULL::TEXT;
    RETURN;
  END IF;

  -- ── outcome = 'failed': refund under window + daily cap ────────────────
  SELECT COUNT(*) INTO v_recent_releases
  FROM public.usage_ledger
  WHERE operation = 'client_release'
    AND metadata->>'identity' = v_identity_key
    AND created_at > now() - interval '24 hours';

  IF now() - v_res.created_at <= v_age_limit AND v_recent_releases < v_refund_cap THEN
    -- Genuine recent failure: restore the deduction.
    IF v_res.reservation_type = 'trial_check' THEN
      IF v_res.user_id IS NOT NULL THEN
        UPDATE public.profiles
        SET trial_checks_remaining = LEAST(COALESCE(trial_checks_total, 5), COALESCE(trial_checks_remaining, 0) + 1),
            trial_checks_used = GREATEST(0, COALESCE(trial_checks_used, 0) - 1),
            updated_at = now()
        WHERE id = v_res.user_id;
      ELSIF v_res.guest_id IS NOT NULL THEN
        UPDATE public.server_guest_sessions
        SET trial_checks_remaining = LEAST(COALESCE(trial_checks_total, 1), COALESCE(trial_checks_remaining, 0) + 1),
            trial_checks_used = GREATEST(0, COALESCE(trial_checks_used, 0) - 1),
            updated_at = now()
        WHERE guest_id = v_res.guest_id;
      END IF;
    ELSE
      UPDATE public.profiles
      SET credits_balance = COALESCE(credits_balance, 0) + COALESCE(v_res.credits_reserved, 0),
          updated_at = now()
      WHERE id = v_res.user_id;
    END IF;

    UPDATE public.credit_reservations
    SET status = 'released', finalized_at = now()
    WHERE id = p_reservation_id;

    INSERT INTO public.usage_ledger (
      user_id, guest_id, feature_slug, operation, credits_amount,
      outcome, reservation_id, ledger_type, metadata
    ) VALUES (
      v_res.user_id, v_res.guest_id, v_res.feature_slug, 'client_release',
      COALESCE(v_res.credits_reserved, 0), 'failed', p_reservation_id, 'refund',
      p_metadata || jsonb_build_object('identity', v_identity_key, 'refunded', true)
    );

    RETURN QUERY SELECT TRUE, TRUE, NULL::TEXT;
    RETURN;
  END IF;

  -- Outside window or over the cap: release WITHOUT restoration.
  UPDATE public.credit_reservations
  SET status = 'released', finalized_at = now()
  WHERE id = p_reservation_id;

  INSERT INTO public.usage_ledger (
    user_id, guest_id, feature_slug, operation, credits_amount,
    outcome, reservation_id, ledger_type, metadata
  ) VALUES (
    v_res.user_id, v_res.guest_id, v_res.feature_slug, 'client_release',
    0, 'failed', p_reservation_id, 'refund',
    p_metadata || jsonb_build_object('identity', v_identity_key, 'refunded', false,
      'reason', CASE WHEN now() - v_res.created_at > v_age_limit THEN 'window_expired' ELSE 'cap_exceeded' END)
  );

  RETURN QUERY SELECT TRUE, FALSE,
    CASE WHEN now() - v_res.created_at > v_age_limit THEN 'refund_window_expired' ELSE 'refund_cap_exceeded' END::TEXT;
END;
$$;


--
-- Name: settle_expired_reservations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."settle_expired_reservations"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth'
    AS $$
DECLARE
  v_res RECORD;
  v_count INT := 0;
BEGIN
  FOR v_res IN
    SELECT * FROM public.credit_reservations
    WHERE status IN ('reserved', 'pending') AND expires_at < now()
    ORDER BY created_at
    FOR UPDATE SKIP LOCKED
  LOOP
    UPDATE public.credit_reservations
    SET status = 'committed', finalized_at = now()
    WHERE id = v_res.id AND status IN ('reserved', 'pending');

    IF v_res.reservation_type = 'trial_check' THEN
      INSERT INTO public.usage_ledger (
        user_id, guest_id, feature_slug, operation, credits_amount, trial_checks_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.guest_id, v_res.feature_slug, 'trial_check_settled', 0, 1,
        'success', v_res.id, 'trial',
        COALESCE(v_res.metadata, '{}'::jsonb) || '{"settled_by":"expiry_sweeper"}'::jsonb
      );
    ELSE
      INSERT INTO public.usage_ledger (
        user_id, guest_id, feature_slug, operation, credits_amount,
        outcome, reservation_id, ledger_type, metadata
      ) VALUES (
        v_res.user_id, v_res.guest_id, v_res.feature_slug, 'credit_deducted', COALESCE(v_res.credits_reserved, 0),
        'success', v_res.id, 'usage',
        COALESCE(v_res.metadata, '{}'::jsonb) || '{"settled_by":"expiry_sweeper"}'::jsonb
      );
    END IF;

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$$;


--
-- Name: submit_report_for_approval("uuid", "uuid"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."submit_report_for_approval"("p_report_id" "uuid", "p_workflow_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_approval_id uuid;
  v_step jsonb;
BEGIN
  IF NOT public.can_view_report(p_report_id) THEN
    RAISE EXCEPTION 'Not allowed to submit report for approval';
  END IF;
  INSERT INTO public.report_approvals (report_id, workflow_id, status, submitted_by, submitted_at)
  VALUES (p_report_id, p_workflow_id, 'pending', auth.uid(), now())
  RETURNING id INTO v_approval_id;
  FOR v_step IN SELECT jsonb_array_elements(steps) FROM public.approval_workflows WHERE id = p_workflow_id LOOP
    INSERT INTO public.approval_steps (approval_id, step_order, approver_user_id, approver_role)
    VALUES (
      v_approval_id,
      (v_step->>'step_order')::int,
      (v_step->>'approver_user_id')::uuid,
      (v_step->>'approver_role')::workspace_role
    );
  END LOOP;
  UPDATE public.collaboration_reports SET approval_status = 'pending' WHERE id = p_report_id;
  RETURN v_approval_id;
END;
$$;


--
-- Name: submit_video_appeal("text", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."submit_video_appeal"("p_job_id" "text", "p_reason" "text", "p_evidence_notes" "text" DEFAULT NULL::"text", "p_original_file_url" "text" DEFAULT NULL::"text", "p_guest_id" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_id UUID := auth.uid();
  v_appeal_id UUID;
BEGIN
  INSERT INTO public.video_appeals (
    job_id,
    user_id,
    guest_id,
    reason,
    evidence_notes,
    original_file_url,
    status
  ) VALUES (
    p_job_id,
    v_user_id,
    COALESCE(p_guest_id, CASE WHEN v_user_id IS NULL THEN 'guest' ELSE NULL END),
    p_reason,
    p_evidence_notes,
    p_original_file_url,
    'pending'
  ) RETURNING id INTO v_appeal_id;

  RETURN jsonb_build_object(
    'success', true,
    'appealId', v_appeal_id,
    'status', 'pending',
    'message', 'Your appeal and supporting production evidence have been submitted for human forensic review.'
  );
END;
$$;


