--
-- Name: trg_lead_events_customer_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."trg_lead_events_customer_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_profile_id uuid;
BEGIN
  v_profile_id := resolve_customer_profile_id(NEW.visitor_id, NEW.user_id);
  NEW.customer_profile_id := v_profile_id;

  IF NEW.event_type = 'page_view' THEN
    UPDATE customer_profiles SET page_views = page_views + 1, updated_at = now() WHERE id = v_profile_id;
  ELSIF NEW.event_type = 'cta_click' THEN
    UPDATE customer_profiles SET cta_clicks = cta_clicks + 1, updated_at = now() WHERE id = v_profile_id;
  ELSIF NEW.event_type = 'popup_conversion' THEN
    UPDATE customer_profiles SET popup_conversions = popup_conversions + 1, updated_at = now() WHERE id = v_profile_id;
  ELSIF NEW.event_type = 'signup' THEN
    UPDATE customer_profiles SET signup_at = COALESCE(signup_at, NEW.created_at), updated_at = now() WHERE id = v_profile_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_profiles_customer_profile(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."trg_profiles_customer_profile"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_profile_id uuid;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_profile_id := get_or_create_customer_profile(NULL, NEW.id);
  ELSE
    SELECT id INTO v_profile_id FROM customer_profiles WHERE user_id = NEW.id;
  END IF;

  IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.email IS NULL AND NEW.email IS NOT NULL) THEN
    UPDATE customer_profiles SET
      email = COALESCE(customer_profiles.email, NEW.email),
      full_name = COALESCE(customer_profiles.full_name, NEW.full_name),
      username = COALESCE(customer_profiles.username, NEW.email),
      role = COALESCE(customer_profiles.role, NEW.role::text, 'user'),
      signup_at = COALESCE(customer_profiles.signup_at, NEW.created_at),
      last_login_at = COALESCE(customer_profiles.last_login_at, NEW.last_login_date),
      subscription_plan = COALESCE(customer_profiles.subscription_plan, NEW.subscription_plan, 'free'),
      account_status = COALESCE(customer_profiles.account_status, NEW.account_status, 'active'),
      subscription_status = COALESCE(customer_profiles.subscription_status, NEW.subscription_status, 'active'),
      updated_at = now()
    WHERE id = v_profile_id;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE customer_profiles SET
      email = COALESCE(NEW.email, customer_profiles.email),
      full_name = COALESCE(NEW.full_name, customer_profiles.full_name),
      role = COALESCE(NEW.role::text, customer_profiles.role),
      last_login_at = COALESCE(NEW.last_login_date, customer_profiles.last_login_at),
      subscription_plan = COALESCE(NEW.subscription_plan, customer_profiles.subscription_plan),
      account_status = COALESCE(NEW.account_status, customer_profiles.account_status),
      subscription_status = COALESCE(NEW.subscription_status, customer_profiles.subscription_status),
      updated_at = now()
    WHERE user_id = NEW.id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: unlock_milestone("uuid", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."unlock_milestone"("p_profile_id" "uuid", "p_milestone_key" "text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO user_milestones (customer_profile_id, milestone_key, unlocked_at)
  VALUES (p_profile_id, p_milestone_key, now())
  ON CONFLICT (customer_profile_id, milestone_key) DO NOTHING;
  RETURN true;
END;
$$;


--
-- Name: update_behavioral_signals("uuid", "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."update_behavioral_signals"("p_user_id" "uuid", "p_signals" "jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_existing jsonb;
  v_confidence int;
begin
  select behavioral_signals into v_existing from user_intelligence_profiles where user_id = p_user_id;
  if found then
    update user_intelligence_profiles
    set behavioral_signals = behavioral_signals || p_signals,
        last_updated = now()
    where user_id = p_user_id;
  else
    insert into user_intelligence_profiles (user_id, behavioral_signals)
    values (p_user_id, p_signals);
  end if;

  select behavioral_signals into v_existing from user_intelligence_profiles where user_id = p_user_id;
  v_confidence := least(100, greatest(0, (select count(*) from jsonb_object_keys(coalesce(v_existing,'{}')))) * 5);
  update user_intelligence_profiles set ai_confidence_score = v_confidence where user_id = p_user_id;
end;
$$;


--
-- Name: update_goal_progress("uuid", "text", integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."update_goal_progress"("p_profile_id" "uuid", "p_goal_key" "text", "p_progress" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  UPDATE user_goals
  SET progress = LEAST(p_progress, target),
      completed = (LEAST(p_progress, target) >= target),
      completed_at = CASE WHEN LEAST(p_progress, target) >= target AND completed = false THEN now() ELSE completed_at END
  WHERE customer_profile_id = p_profile_id AND goal_key = p_goal_key;
  RETURN true;
END;
$$;


