--
-- Name: upsert_communication_preferences("uuid", boolean, boolean, boolean, boolean, boolean, boolean, boolean, boolean, boolean, integer, "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."upsert_communication_preferences"("p_user_id" "uuid", "p_product_tips" boolean DEFAULT NULL::boolean, "p_feature_updates" boolean DEFAULT NULL::boolean, "p_security_notifications" boolean DEFAULT NULL::boolean, "p_billing_notifications" boolean DEFAULT NULL::boolean, "p_marketing_communications" boolean DEFAULT NULL::boolean, "p_weekly_summaries" boolean DEFAULT NULL::boolean, "p_email" boolean DEFAULT NULL::boolean, "p_in_app" boolean DEFAULT NULL::boolean, "p_dashboard_announcements" boolean DEFAULT NULL::boolean, "p_max_messages_per_day" integer DEFAULT NULL::integer, "p_timezone" "text" DEFAULT NULL::"text", "p_quiet_hours_start" "text" DEFAULT NULL::"text", "p_quiet_hours_end" "text" DEFAULT NULL::"text") RETURNS "public"."communication_preferences"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_result public.communication_preferences;
BEGIN
  IF p_user_id IS DISTINCT FROM v_user_id THEN
    RAISE EXCEPTION 'User ID does not match authenticated user';
  END IF;

  INSERT INTO public.communication_preferences (
    user_id, product_tips, feature_updates, security_notifications, billing_notifications,
    marketing_communications, weekly_summaries, email_enabled, in_app_enabled, dashboard_announcements_enabled,
    max_messages_per_day, timezone, quiet_hours_start, quiet_hours_end
  ) VALUES (
    v_user_id,
    COALESCE(p_product_tips, true),
    COALESCE(p_feature_updates, true),
    COALESCE(p_security_notifications, true),
    COALESCE(p_billing_notifications, true),
    COALESCE(p_marketing_communications, true),
    COALESCE(p_weekly_summaries, true),
    COALESCE(p_email, true),
    COALESCE(p_in_app, true),
    COALESCE(p_dashboard_announcements, true),
    COALESCE(p_max_messages_per_day, 5),
    NULLIF(TRIM(p_timezone), ''),
    NULLIF(TRIM(p_quiet_hours_start), '')::time without time zone,
    NULLIF(TRIM(p_quiet_hours_end), '')::time without time zone
  )
  ON CONFLICT (user_id) DO UPDATE SET
    product_tips = EXCLUDED.product_tips,
    feature_updates = EXCLUDED.feature_updates,
    security_notifications = EXCLUDED.security_notifications,
    billing_notifications = EXCLUDED.billing_notifications,
    marketing_communications = EXCLUDED.marketing_communications,
    weekly_summaries = EXCLUDED.weekly_summaries,
    email_enabled = EXCLUDED.email_enabled,
    in_app_enabled = EXCLUDED.in_app_enabled,
    dashboard_announcements_enabled = EXCLUDED.dashboard_announcements_enabled,
    max_messages_per_day = EXCLUDED.max_messages_per_day,
    timezone = EXCLUDED.timezone,
    quiet_hours_start = EXCLUDED.quiet_hours_start,
    quiet_hours_end = EXCLUDED.quiet_hours_end,
    updated_at = now()
  RETURNING * INTO v_result;

  RETURN v_result;
END;
$$;


--
-- Name: upsert_customer_device("uuid", "text", "text", "text", "text", "text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."upsert_customer_device"("p_profile_id" "uuid", "p_device_type" "text", "p_browser" "text", "p_os" "text", "p_screen_resolution" "text", "p_language" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  INSERT INTO customer_devices (customer_profile_id, device_type, browser, os, screen_resolution, language)
  VALUES (p_profile_id, p_device_type, p_browser, p_os, p_screen_resolution, p_language)
  ON CONFLICT (customer_profile_id, device_type, browser, os, screen_resolution)
  DO UPDATE SET last_seen_at = now(), session_count = customer_devices.session_count + 1;
END;
$$;


--
-- Name: upsert_prediction("uuid", "text", integer, numeric, integer, "jsonb"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."upsert_prediction"("p_user_id" "uuid", "p_prediction_type" "text", "p_score" integer, "p_value" numeric DEFAULT NULL::numeric, "p_confidence" integer DEFAULT 50, "p_features" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_threshold int;
  v_existing_score int;
  v_already_triggered boolean;
  v_config jsonb;
begin
  select thresholds, model_settings into v_config from personalization_config where id = 1;
  if not coalesce((v_config->'prediction_models'->p_prediction_type)::boolean, true) then
    return;
  end if;

  v_threshold := case p_prediction_type
    when 'churn' then (v_config->>'high_churn_risk')::int
    when 'upgrade' then (v_config->>'high_upgrade_probability')::int
    when 'renewal' then (v_config->>'low_renewal_probability')::int
    when 'support_risk' then (v_config->>'high_support_risk')::int
    else null
  end;

  select score, triggered into v_existing_score, v_already_triggered
  from user_predictions where user_id = p_user_id and prediction_type = p_prediction_type;

  insert into user_predictions (user_id, prediction_type, score, value, confidence, features, expires_at)
  values (p_user_id, p_prediction_type, p_score, p_value, p_confidence, p_features, now() + interval '7 days')
  on conflict (user_id, prediction_type) do update set
    score = EXCLUDED.score,
    value = EXCLUDED.value,
    confidence = EXCLUDED.confidence,
    features = EXCLUDED.features,
    updated_at = now(),
    expires_at = EXCLUDED.expires_at;

  if v_threshold is not null then
    if (p_prediction_type in ('churn','support_risk') and p_score >= v_threshold and not v_already_triggered)
       or (p_prediction_type = 'upgrade' and p_score >= v_threshold and not v_already_triggered)
       or (p_prediction_type = 'renewal' and p_score <= v_threshold and not v_already_triggered) then
      update user_predictions set triggered = true, triggered_at = now()
      where user_id = p_user_id and prediction_type = p_prediction_type;
      insert into automation_events (event_type, user_id, event_data, processed)
      values ('prediction_'||p_prediction_type, p_user_id, jsonb_build_object('score', p_score), false);
    end if;
  end if;
end;
$$;


--
-- Name: verify_authorship_content_hash("text"); Type: FUNCTION; Schema: public; Owner: -
--

CREATE OR REPLACE FUNCTION "public"."verify_authorship_content_hash"("p_hash" "text") RETURNS TABLE("id" "uuid", "tracking_code" "text", "title" "text", "status" "text", "created_at" timestamp with time zone, "is_match" boolean)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
    SELECT 
        r.id,
        r.tracking_code,
        r.title,
        r.status,
        r.created_at,
        (r.content_hash = p_hash) AS is_match
    FROM public.authorship_registrations r
    WHERE r.content_hash = p_hash
    UNION
    SELECT 
        r.id,
        v.version_tracking_code AS tracking_code,
        v.title,
        r.status,
        v.created_at,
        (v.content_hash = p_hash) AS is_match
    FROM public.authorship_versions v
    JOIN public.authorship_registrations r ON r.id = v.registration_id
    WHERE v.content_hash = p_hash;
$$;


